package com.voicecomic.app.data

import android.content.Context
import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.Json
import java.io.File

/**
 * Хранилище проекта: файлы в каталоге приложения вместо IndexedDB.
 *
 * projects/<id>/project.json   — весь проект (страницы, роли, клипы, настройки)
 * projects/<id>/pages/<id>.*   — изображения страниц
 * projects/<id>/clips/<id>/seg-N.wav — нарезки клипов
 * projects/<id>/bubbles/<id>.wav — озвучка конкретной реплики
 * projects/<id>/music.*        — фоновая музыка
 * last-project                 — id последнего открытого проекта
 */
class ProjectStore(context: Context) {
    private val app = context.applicationContext
    val root: File = File(app.filesDir, "projects").apply { mkdirs() }

    private val json = Json {
        prettyPrint = true
        ignoreUnknownKeys = true
        encodeDefaults = true
    }

    fun projectDir(id: String): File = File(root, id).apply { mkdirs() }
    fun pagesDir(id: String): File = File(projectDir(id), "pages").apply { mkdirs() }
    fun clipsDir(id: String): File = File(projectDir(id), "clips").apply { mkdirs() }
    fun bubblesDir(id: String): File = File(projectDir(id), "bubbles").apply { mkdirs() }

    fun pageFile(id: String, name: String): File = File(pagesDir(id), name)
    fun segFile(id: String, name: String): File = File(File(clipsDir(id), id), name)
    fun bubbleFile(id: String, name: String): File = File(bubblesDir(id), name)
    fun musicFile(id: String, name: String): File = File(projectDir(id), name)

    fun resolve(projectId: String, relative: String): File = File(projectDir(projectId), relative)

    fun listProjects(): List<File> = root.listFiles()?.filter { File(it, "project.json").exists() }
        ?.sortedByDescending { it.lastModified() } ?: emptyList()

    fun lastProjectId(): String? = File(app.filesDir, "last-project").takeIf { it.exists() }
        ?.readText()?.trim()?.takeIf { it.isNotEmpty() }

    fun setLastProject(id: String) {
        File(app.filesDir, "last-project").writeText(id)
    }

    fun newProjectId(): String = "p" + System.currentTimeMillis().toString(36) + newId().take(4)

    suspend fun save(projectId: String, project: Project, settings: Settings) = withContext(Dispatchers.IO) {
        val dir = projectDir(projectId)
        val tmp = File(dir, "project.json.tmp")
        tmp.writeText(
            buildString {
                append("{\n")
                append("  \"version\": 2,\n")
                append("  \"projectId\": ").append(Json.encodeToString(String.serializer(), projectId)).append(",\n")
                append("  \"settings\": ").append(json.encodeToString(Settings.serializer(), settings)).append(",\n")
                append("  \"project\": ").append(json.encodeToString(Project.serializer(), project))
                append("\n}\n")
            }
        )
        if (!tmp.renameTo(File(dir, "project.json"))) {
            File(dir, "project.json").writeText(tmp.readText())
            tmp.delete()
        }
    }

    data class Loaded(val projectId: String, val project: Project, val settings: Settings)

    suspend fun load(projectId: String): Loaded? = withContext(Dispatchers.IO) {
        val f = File(projectDir(projectId), "project.json")
        if (!f.exists()) return@withContext null
        runCatching {
            val txt = f.readText()
            val pid = Regex("\"projectId\"\\s*:\\s*\"([^\"]+)\"").find(txt)?.groupValues?.get(1) ?: projectId
            val settings = Regex("\"settings\"\\s*:").find(txt)?.let { m ->
                val start = m.range.last + 1
                val slice = txt.substring(start).trim()
                json.decodeFromString(Settings.serializer(), slice.objValue("settings"))
            } ?: Settings()
            val project = json.decodeFromString(Project.serializer(), txt.objValue("project"))
            Loaded(pid, project, settings)
        }.onFailure { Log.e("ProjectStore", "load failed", it) }.getOrNull()
    }

    /** Вырезает сбалансированный JSON-фрагмент по имени ключа верхнего уровня. */
    private fun String.objValue(key: String): String {
        val k = "\"$key\""
        val idx = indexOf(k)
        if (idx < 0) return "{}"
        var i = indexOf(':', idx) + 1
        while (i < length && (this[i].isWhitespace() || this[i] == '{' || this[i] == '[')) {
            if (this[i] == '{' || this[i] == '[') break
            i++
        }
        val start = i
        val open = this[i]
        val close = if (open == '{') '}' else ']'
        var depth = 0
        var inStr = false
        var esc = false
        var j = start
        while (j < length) {
            val c = this[j]
            if (inStr) {
                when {
                    esc -> esc = false
                    c == '\\' -> esc = true
                    c == '"' -> inStr = false
                }
            } else {
                when (c) {
                    '"' -> inStr = true
                    open -> depth++
                    close -> {
                        depth--
                        if (depth == 0) return substring(start, j + 1)
                    }
                }
            }
            j++
        }
        return "{}"
    }

    fun delete(projectId: String) {
        projectDir(projectId).deleteRecursively()
    }

    fun exportsDir(): File = File(app.filesDir, "exports").apply { mkdirs() }
}

package com.voicecomic.app.data

import android.content.Context
import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.io.File

@Serializable
data class ProjectFile(
    val version: Int = 2,
    val projectId: String = "",
    val settings: Settings = Settings(),
    val project: Project = Project()
)

/**
 * Хранилище проекта: файлы в каталоге приложения вместо IndexedDB.
 *
 * projects/<id>/project.json      — проект, роли, клипы, настройки
 * projects/<id>/pages/<file>      — изображения страниц
 * projects/<id>/clips/<id>/*.wav  — нарезки клипов
 * projects/<id>/bubbles/*.wav     — озвучка реплик
 * projects/<id>/music.*           — фоновая музыка
 */
class ProjectStore(context: Context) {
    private val app = context.applicationContext
    val root: File = File(app.filesDir, "projects").apply { mkdirs() }

    private val json = Json {
        prettyPrint = true
        ignoreUnknownKeys = true
        encodeDefaults = true
    }

    fun projectDir(id: String): File = File(root, id).apply { mkdirs() }
    fun pagesDir(id: String): File = File(projectDir(id), "pages").apply { mkdirs() }
    fun clipsDir(id: String): File = File(projectDir(id), "clips").apply { mkdirs() }
    fun bubblesDir(id: String): File = File(projectDir(id), "bubbles").apply { mkdirs() }

    fun pageFile(id: String, name: String): File = File(pagesDir(id), name)
    fun segFile(clipId: String, name: String): File = File(File(clipsDir(id2(clipId)), clipId), name)
    private fun id2(v: String) = v
    fun bubbleFile(id: String, name: String): File = File(bubblesDir(id), name)

    fun resolve(projectId: String, relative: String): File = File(projectDir(projectId), relative)

    fun listProjects(): List<File> = root.listFiles()
        ?.filter { File(it, "project.json").exists() }
        ?.sortedByDescending { it.lastModified() }
        ?: emptyList()

    fun lastProjectId(): String? = File(app.filesDir, "last-project")
        .takeIf { it.exists() }?.readText()?.trim()?.takeIf { it.isNotEmpty() }

    fun setLastProject(id: String) {
        File(app.filesDir, "last-project").writeText(id)
    }

    fun newProjectId(): String = "p" + System.currentTimeMillis().toString(36) + newId().take(4)

    private fun file(projectId: String) = File(projectDir(projectId), "project.json")

    suspend fun save(projectId: String, project: Project, settings: Settings) =
        withContext(Dispatchers.IO) {
            val target = file(projectId)
            val tmp = File(target.parentFile, "project.json.tmp")
            tmp.writeText(
                json.encodeToString(
                    ProjectFile.serializer(),
                    ProjectFile(version = 2, projectId = projectId, settings = settings, project = project)
                )
            )
            if (!tmp.renameTo(target)) {
                target.writeText(tmp.readText())
                tmp.delete()
            }
        }

    suspend fun load(projectId: String): ProjectFile? = withContext(Dispatchers.IO) {
        val f = file(projectId)
        if (!f.exists()) return@withContext null
        runCatching { json.decodeFromString(ProjectFile.serializer(), f.readText()) }
            .onFailure { Log.e("ProjectStore", "не удалось прочитать проект $projectId", it) }
            .getOrNull()
    }

    /** Экспорт сценария без картинок и звука (совместим с веб-версией по полям). */
    fun exportScenario(project: Project, settings: Settings): String = json.encodeToString(
        ProjectFile.serializer(),
        ProjectFile(version = 1, projectId = "", settings = settings, project = project)
    )

    fun delete(projectId: String) {
        projectDir(projectId).deleteRecursively()
    }

    fun exportsDir(): File = File(app.filesDir, "exports").apply { mkdirs() }
}

package com.voicecomic.app.audio

import java.io.File
import java.io.RandomAccessFile
import kotlin.math.abs
import kotlin.math.ceil
import kotlin.math.max
import kotlin.math.min
import kotlin.math.roundToInt
import kotlin.math.sqrt

/** Утилиты PCM: моно-микс, ресемплинг, обрезка тишины, нарезка по паузам, WAV. */
object Pcm {

    const val MIX_RATE = 44100

    data class Trim(val start: Int, val end: Int)

    /** Склеивает все каналы усреднением (как в веб-версии). */
    fun toMono(buffers: Array<FloatArray>, frames: Int): FloatArray {
        val ch = buffers.size
        if (ch == 1) return buffers[0].let { if (it.size >= frames) it.copyOf(frames) else it.copyOf(frames) }
        val out = FloatArray(frames)
        for (c in buffers) {
            for (i in 0 until min(frames, c.size)) out[i] += c[i] / ch
        }
        return out
    }

    /** Линейный ресемплинг, точная копия resampleLinear из веб-версии. */
    fun resampleLinear(src: FloatArray, fromSr: Int, toSr: Int): FloatArray {
        if (fromSr == toSr) return src
        val step = fromSr.toDouble() / toSr
        val n = (src.size * toSr / fromSr.toDouble()).toInt().coerceAtLeast(0)
        val out = FloatArray(n)
        for (i in 0 until n) {
            val x = i * step
            val i0 = x.toInt()
            val i1 = min(i0 + 1, src.size - 1)
            val t = (x - i0).toFloat()
            out[i] = src[i0.coerceIn(0, src.size - 1)] * (1 - t) + src[i1] * t
        }
        return out
    }

    /**
     * Обрезка тишины по окнам. threshold — пиковый порог, margin — отступ в секундах.
     * Покрывает util.trimSilence и engine.TRIM (порог/отступ задаются вызывающим).
     */
    fun trimSilence(
        samples: FloatArray,
        sr: Int,
        threshold: Double = 0.02,
        margin: Double = 0.09,
        winMs: Int = 10
    ): Trim {
        val n = samples.size
        if (n == 0) return Trim(0, 0)
        val win = max(1, (sr * winMs / 1000.0).toInt())
        val pad = max(1, (sr * margin).toInt())
        var start = 0
        var end = 0
        var i = 0
        var found = false
        while (i + win <= n) {
            var peak = 0f
            var k = i
            while (k < i + win) {
                val v = abs(samples[k])
                if (v > peak) peak = v
                k++
            }
            if (peak > threshold) {
                start = max(0, i - pad)
                found = true
                break
            }
            i += win
        }
        if (!found) return Trim(0, 0)
        i = n
        var foundEnd = false
        while (i - win >= 0) {
            var peak = 0f
            var k = max(0, i - win)
            while (k < i) {
                val v = abs(samples[k])
                if (v > peak) peak = v
                k++
            }
            if (peak > threshold) {
                end = min(n, i + pad)
                foundEnd = true
                break
            }
            i -= win
        }
        if (!foundEnd) end = n
        return Trim(start, max(start, end))
    }

    data class Seg(val startS: Double, val endS: Double)

    /**
     * Нарезка по тишине. window активности — RMS > threshold, тишина длиной не меньше
     * minSilence завершает фразу, фраза короче minClip выбрасывается, длиннее maxClip режется.
     */
    fun sliceSegments(
        samples: FloatArray,
        sr: Int,
        threshold: Double = 0.02,
        minSilence: Double = 0.32,
        minClip: Double = 0.3,
        maxClip: Double = 16.0,
        winMs: Int = 40
    ): List<Seg> {
        val n = samples.size
        if (n == 0) return emptyList()
        val win = max(1, (sr * winMs / 1000.0).toInt())
        val steps = n / win
        val active = BooleanArray(steps + 1)
        for (k in 0 until steps) {
            var sum = 0.0
            val base = k * win
            for (j in base until base + win) {
                val v = samples[j].toDouble()
                sum += v * v
            }
            active[k] = (sum / win) > threshold * threshold
        }
        val minSil = max(1, (minSilence / (winMs / 1000.0)).toInt())
        val out = ArrayList<Seg>()
        var inClip = false
        var cStart = 0
        var cEnd = 0
        var silence = 0
        for (k in 0..steps) {
            val act = k < steps && active[k]
            if (act) {
                if (!inClip) {
                    inClip = true
                    cStart = k
                }
                silence = 0
                cEnd = k
            } else if (inClip) {
                silence++
                if (silence >= minSil) {
                    emit(out, cStart, cEnd, win, sr, n, minClip, maxClip)
                    inClip = false
                }
            }
        }
        if (inClip) emit(out, cStart, cEnd, win, sr, n, minClip, maxClip)
        return out
    }

    private fun emit(
        out: MutableList<Seg>, cStart: Int, cEnd: Int, win: Int, sr: Int,
        n: Int, minClip: Double, maxClip: Double
    ) {
        val s = cStart * win.toDouble() / sr
        val e = min(n, (cEnd + 1) * win).toDouble() / sr
        if (e - s >= minClip) out.add(Seg(s, min(e, s + maxClip)))
    }

    fun floatToPcm16(src: FloatArray, from: Int = 0, count: Int = src.size - from): ShortArray {
        val n = min(count, src.size - from).coerceAtLeast(0)
        val out = ShortArray(n)
        for (i in 0 until n) {
            val v = src[from + i].coerceIn(-1f, 1f)
            out[i] = (if (v < 0) v * 0x8000 else v * 0x7fff).toInt().toShort()
        }
        return out
    }

    fun pcm16ToFloat(src: ShortArray): FloatArray {
        val out = FloatArray(src.size)
        for (i in src.indices) out[i] = src[i] / 32768f
        return out
    }

    /** WAV 16-bit mono — тот же формат, что samplesToWav в веб-версии. */
    fun writeWav(file: File, pcm: ShortArray, sr: Int) {
        val dataLen = pcm.size * 2
        file.parentFile?.mkdirs()
        RandomAccessFile(file, "rw").use { raf ->
            raf.setLength(0)
            val h = ByteArray(44)
            fun putStr(off: Int, s: String) = s.toByteArray(Charsets.US_ASCII).copyInto(h, off)
            fun putLe32(off: Int, v: Int) {
                h[off] = (v and 0xff).toByte(); h[off + 1] = ((v shr 8) and 0xff).toByte()
                h[off + 2] = ((v shr 16) and 0xff).toByte(); h[off + 3] = ((v shr 24) and 0xff).toByte()
            }

            fun putLe16(off: Int, v: Int) {
                h[off] = (v and 0xff).toByte(); h[off + 1] = ((v shr 8) and 0xff).toByte()
            }

            putStr(0, "RIFF"); putLe32(4, 36 + dataLen); putStr(8, "WAVE")
            putStr(12, "fmt "); putLe32(16, 16); putLe16(20, 1); putLe16(22, 1)
            putLe32(24, sr); putLe32(28, sr * 2); putLe16(32, 2); putLe16(34, 16)
            putStr(36, "data"); putLe32(40, dataLen)
            raf.write(h)
            val bytes = ByteArray(dataLen)
            var i = 0
            while (i < pcm.size) {
                val v = pcm[i].toInt()
                bytes[i * 2] = (v and 0xff).toByte()
                bytes[i * 2 + 1] = ((v shr 8) and 0xff).toByte()
                i++
            }
            raf.write(bytes)
        }
    }

    fun readWav(file: File): Pair<FloatArray, Int>? {
        val bytes = file.readBytes()
        if (bytes.size < 44) return null
        val sr = (bytes[24].toInt() and 0xff) or ((bytes[25].toInt() and 0xff) shl 8) or
            ((bytes[26].toInt() and 0xff) shl 16) or ((bytes[27].toInt() and 0xff) shl 24)
        val channels = (bytes[22].toInt() and 0xff) or ((bytes[23].toInt() and 0xff) shl 8)
        val bits = (bytes[34].toInt() and 0xff) or ((bytes[35].toInt() and 0xff) shl 8)
        if (bits != 16) return null
        // ищем начало data-чанка
        var off = 12
        while (off + 8 <= bytes.size) {
            val id = String(bytes, off, 4, Charsets.US_ASCII)
            val size = (bytes[off + 4].toInt() and 0xff) or ((bytes[off + 5].toInt() and 0xff) shl 8) or
                ((bytes[off + 6].toInt() and 0xff) shl 16) or ((bytes[off + 7].toInt() and 0xff) shl 24)
            if (id == "data") {
                off += 8
                val frames = (bytes.size - off) / 2 / max(1, channels)
                val out = FloatArray(frames)
                var i = 0
                while (i < frames) {
                    var acc = 0f
                    for (c in 0 until max(1, channels)) {
                        val p = off + (i * channels + c) * 2
                        if (p + 1 >= bytes.size) break
                        val v = ((bytes[p].toInt() and 0xff) or ((bytes[p + 1].toInt() and 0xff) shl 8)).toShort()
                        acc += v / 32768f
                    }
                    out[i] = acc / max(1, channels)
                    i++
                }
                return out to sr
            }
            off += 8 + size + (size and 1)
        }
        return null
    }

    fun durationSeconds(pcm: FloatArray, sr: Int): Double = pcm.size.toDouble() / sr

    fun rms(samples: FloatArray, from: Int, len: Int): Double {
        val n = min(len, samples.size - from).coerceAtLeast(0)
        if (n == 0) return 0.0
        var sum = 0.0
        for (i in 0 until n) {
            val v = samples[from + i].toDouble()
            sum += v * v
        }
        return sqrt(sum / n)
    }

    /** Оценка длительности реплики без озвучки — 13 символов/с, как в веб-версии. */
    fun estimateSpeakDuration(text: String): Double {
        if (text.isBlank()) return 0.0
        val len = text.length
        val base = max(1.1, min(14.0, len / 13.0 + 0.55))
        return base + if (text.any { it.isWhitespace() }) 0.15 else 0.0
    }

    fun framesFor(duration: Double, sr: Int): Int = ceil(duration * sr).toInt()
}

package com.voicecomic.app.audio

import android.media.AudioFormat
import android.media.MediaCodec
import android.media.MediaExtractor
import android.media.MediaFormat
import java.io.File
import java.nio.ByteBuffer

/** Декодер звука/видео через MediaExtractor + MediaCodec (замена decodeAudioData). */
object MediaAudioDecoder {

    class Result(val samples: FloatArray, val sr: Int, val duration: Double)

    fun decode(file: File, maxSeconds: Double = 0.0): Result? = runCatching {
        val extractor = MediaExtractor()
        extractor.setDataSource(file.absolutePath)

        var track = -1
        var format: MediaFormat? = null
        for (i in 0 until extractor.trackCount) {
            val f = extractor.getTrackFormat(i)
            val mime = f.getString(MediaFormat.KEY_MIME) ?: continue
            if (mime.startsWith("audio/")) {
                track = i
                format = f
                break
            }
        }
        if (track < 0 || format == null) {
            extractor.release()
            return null
        }
        extractor.selectTrack(track)
        val mime = format.getString(MediaFormat.KEY_MIME)!!
        val codec = MediaCodec.createDecoderByType(mime)
        codec.configure(format, null, null, 0)
        codec.start()

        val chunks = ArrayList<FloatArray>()
        var total = 0
        var srcSr = format.getInteger(MediaFormat.KEY_SAMPLE_RATE)
        var srcCh = format.getInteger(MediaFormat.KEY_CHANNEL_COUNT)
        var sawInputEos = false
        var sawOutputEos = false
        val info = MediaCodec.BufferInfo()
        var pcmEncoding = AudioFormat.ENCODING_PCM_16BIT
        val limitFrames = if (maxSeconds > 0) (maxSeconds * srcSr).toInt() else Int.MAX_VALUE

        while (!sawOutputEos) {
            if (!sawInputEos) {
                val inIdx = codec.dequeueInputBuffer(10_000)
                if (inIdx >= 0) {
                    val buf = codec.getInputBuffer(inIdx)
                    val size = if (buf != null) extractor.readSampleData(buf, 0) else -1
                    if (size < 0) {
                        codec.queueInputBuffer(
                            inIdx, 0, 0, 0, MediaCodec.BUFFER_FLAG_END_OF_STREAM
                        )
                        sawInputEos = true
                    } else {
                        codec.queueInputBuffer(inIdx, 0, size, extractor.sampleTime, 0)
                        extractor.advance()
                    }
                }
            }
            val outIdx = codec.dequeueOutputBuffer(info, 10_000)
            if (outIdx >= 0) {
                if (info.size > 0 && total < limitFrames) {
                    val out = codec.getOutputBuffer(outIdx)
                    if (out != null) {
                        out.position(info.offset)
                        out.limit(info.offset + info.size)
                        val n = info.size / 2
                        val shorts = ShortArray(n)
                        out.asShortBuffer().get(shorts, 0, n)
                        val frames = n / max(1, srcCh)
                        val mono = FloatArray(frames)
                        for (f in 0 until frames) {
                            var acc = 0f
                            for (c in 0 until srcCh) {
                                val idx = f * srcCh + c
                                if (idx < n) acc += shorts[idx] / 32768f
                            }
                            mono[f] = acc / max(1, srcCh)
                        }
                        chunks.add(mono)
                        total += frames
                    }
                }
                codec.releaseOutputBuffer(outIdx, false)
                if (info.flags and MediaCodec.BUFFER_FLAG_END_OF_STREAM != 0) sawOutputEos = true
            }
            if (info.flags and MediaCodec.BUFFER_FLAG_FORMAT_CHANGED != 0) {
                val of = codec.outputFormat
                srcSr = of.getInteger(MediaFormat.KEY_SAMPLE_RATE)
                srcCh = of.getInteger(MediaFormat.KEY_CHANNEL_COUNT)
                pcmEncoding = of.getInteger(MediaFormat.KEY_PCM_ENCODING)
            }
            if (chunks.sumOf { it.size } > limitFrames) break
        }
        codec.stop()
        codec.release()
        extractor.release()

        val samples = FloatArray(total)
        var off = 0
        for (c in chunks) {
            System.arraycopy(c, 0, samples, off, c.size)
            off += c.size
        }
        Result(samples, srcSr, samples.size.toDouble() / srcSr)
    }.getOrNull()

    /** Декодер в PCM 16 kHz моно для MediaCodec-энкодера AAC. */
    fun toPcm16(file: File): Pair<ShortArray, Int>? {
        val r = decode(file) ?: return null
        val target = if (r.sr == Pcm.MIX_RATE) r.samples else Pcm.resampleLinear(r.samples, r.sr, Pcm.MIX_RATE)
        return Pcm.floatToPcm16(target) to Pcm.MIX_RATE
    }

    @Suppress("unused")
    private fun ByteBuffer.ignored() = Unit
}

package com.voicecomic.app.audio

import java.security.MessageDigest

/**
 * Токен Sec-MS-GEC для Edge-TTS: SHA-256 от метки времени в 100-насных тиках
 * Windows-эпохи, округлённой к началу 5-минутного окна, плюс trusted client token.
 */
object Gec {
    const val TRUSTED_CLIENT_TOKEN = "6A5AA1D4EAFF4E9FB37E23D68491D6F4"
    const val WIN_EPOCH_SEC = 11644473600L
    const val CHROMIUM = "143.0.3650.75"
    const val GEC_VERSION = "1-$CHROMIUM"

    fun value(nowMs: Long = System.currentTimeMillis()): String {
        var s = nowMs / 1000.0 + WIN_EPOCH_SEC
        s -= s % 300
        val ticks = Math.round(s * 1e7)
        val raw = ticks.toString() + TRUSTED_CLIENT_TOKEN
        val sha = MessageDigest.getInstance("SHA-256").digest(raw.toByteArray(Charsets.UTF_8))
        val sb = StringBuilder(32)
        for (b in sha) {
            val v = b.toInt() and 0xff
            if (v < 16) sb.append('0')
            sb.append(Integer.toHexString(v).uppercase())
        }
        return sb.toString()
    }
}

/** Вычищает межкадровый мусор из потока MP3, который Edge присылает в бинарных кадрах. */
object Mp3Frames {
    private val BR_V1 = intArrayOf(0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320)
    private val BR_V2 = intArrayOf(0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160)
    private val SR_V1 = intArrayOf(44100, 48000, 32000)
    private val SR_V2 = intArrayOf(22050, 24000, 16000)
    private val SR_V25 = intArrayOf(11025, 12000, 8000)

    fun clean(bytes: ByteArray): ByteArray {
        val out = java.io.ByteArrayOutputStream(bytes.size)
        val n = bytes.size
        var i = 0
        while (i < n - 4) {
            val b0 = bytes[i].toInt() and 0xff
            val b1 = bytes[i + 1].toInt() and 0xff
            if (b0 == 0xff && (b1 and 0xe0) == 0xe0) {
                val h = ((b0.toLong() shl 24) or (b1.toLong() shl 16) or
                    ((bytes[i + 2].toInt() and 0xff).toLong() shl 8) or
                    (bytes[i + 3].toLong() and 0xff)).toInt()
                val ver = (h ushr 19) and 3
                val layer = (h ushr 17) and 3
                val brI = (h ushr 12) and 0xf
                val srI = (h ushr 10) and 3
                val pad = (h ushr 9) and 1
                if ((ver == 3 || ver == 2 || ver == 0) && layer == 1 && brI != 0 && brI != 0xf && srI != 3) {
                    val br: Int
                    val sr: Int
                    when (ver) {
                        3 -> { br = BR_V1[brI]; sr = SR_V1[srI] }
                        2 -> { br = BR_V2[brI]; sr = SR_V2[srI] }
                        else -> { br = BR_V2[brI]; sr = SR_V25[srI] }
                    }
                    val len = (if (ver == 3) 144 else 72) * br * 1000 / sr + pad
                    if (br != 0 && sr != 0 && len > 0 && i + len <= n) {
                        out.write(bytes, i, len)
                        i += len
                        continue
                    }
                }
            }
            i++
        }
        return out.toByteArray()
    }
}

package com.voicecomic.app.audio

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.Response
import okhttp3.WebSocket
import okhttp3.WebSocketListener
import okio.ByteString
import java.io.ByteArrayOutputStream
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.TimeZone
import java.util.concurrent.TimeUnit

/**
 * Edge-TTS через WSS — нативный клиент вместо voices.js.
 * Протокол и все константы перенесены один в один (см. комментарии про 403 и заголовки).
 */
class EdgeTts(private val client: OkHttpClient) {

    companion object {
        private const val HOST = "speech.platform.bing.com"
        private const val PATH = "/consumer/speech/synthesize/readaloud"
        private const val OUTPUT_FORMAT = "audio-24khz-48kbitrate-mono-mp3"
        private val CLIENT = OkHttpClient.Builder()
            .readTimeout(65, TimeUnit.SECONDS)
            .connectTimeout(20, TimeUnit.SECONDS)
            .build()
    }

    data class Word(val offsetMs: Double, val durMs: Double, val text: String)

    class Synthesis(val mp3: ByteArray, val words: List<Word>)

    private val http = if (client === CLIENT) CLIENT else client

    /** RFC-1123 с «+0000» вместо GMT — сервер не принимает другие форматы. */
    private fun nowEdgeString(): String {
        val f = SimpleDateFormat("EEE, dd MMM yyyy HH:mm:ss", Locale.US)
        f.timeZone = TimeZone.getTimeZone("UTC")
        return f.format(Date()) + " GMT+0000"
    }

    fun voiceLocale(voiceId: String): String {
        val m = Regex("^\\s*([a-z]{2,3})-([A-Za-z]{2}|[0-9]{3})\\b").find(voiceId)
        return if (m != null) "${m.groupValues[1]}-${m.groupValues[2]}" else "en-US"
    }

    fun ssml(text: String, voice: String, pitch: String, rate: String, volume: String, style: String): String {
        val lang = voiceLocale(voice)
        val body = escape(text)
        val prosody = "<prosody pitch='$pitch' rate='$rate' volume='$volume'>$body</prosody>"
        val inner = if (style.isNotEmpty()) {
            "<mstts:express-as style='$style' styledegree='1'>$prosody</mstts:express-as>"
        } else prosody
        val mstts = if (style.isNotEmpty()) " xmlns:mstts='http://www.w3.org/2001/mstts'" else ""
        return "<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis'$mstts xml:lang='$lang'>" +
            "<voice name='$voice'>$inner</voice></speak>"
    }

    private fun escape(s: String): String {
        val sb = StringBuilder(s.length + 16)
        for (ch in s) {
            val c = ch.code
            val drop = (c in 0x00..0x08) || (c in 0x0B..0x0C) || (c in 0x0E..0x1F)
            when {
                drop -> sb.append(' ')
                ch == '&' -> sb.append("&amp;")
                ch == '<' -> sb.append("&lt;")
                ch == '>' -> sb.append("&gt;")
                ch == '"' -> sb.append("&quot;")
                ch == '\'' -> sb.append("&apos;")
                else -> sb.append(ch)
            }
        }
        return sb.toString()
    }

    suspend fun synthesize(
        text: String,
        voice: String,
        pitch: String = "+0Hz",
        rate: String = "+0%",
        volume: String = "+0%",
        style: String = ""
    ): Synthesis = withContext(Dispatchers.IO) {
        val requestId = com.voicecomic.app.data.newId()
        val gec = Gec.value()
        val url = "wss://$HOST$PATH/edge/v1" +
            "?TrustedClientToken=${Gec.TRUSTED_CLIENT_TOKEN}" +
            "&ConnectionId=$requestId" +
            "&Sec-MS-GEC=$gec" +
            "&Sec-MS-GEC-Version=${Gec.GEC_VERSION}"
        val request = Request.Builder().url(url)
            .header("Origin", "https://$HOST")
            .header("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 " +
                "(KHTML, like Gecko) Chrome/${Gec.CHROMIUM}.0.0.0 Safari/537.36 Edg/${Gec.CHROMIUM}.0.0.0")
            .build()

        val audio = ByteArrayOutputStream()
        val words = ArrayList<Word>()
        val done = kotlinx.coroutines.CompletableDeferred<Synthesis>()
        var ended = false

        val socket = http.newWebSocket(request, object : WebSocketListener() {
            override fun onOpen(webSocket: WebSocket, response: Response) {
                val ts = nowEdgeString()
                webSocket.send(
                    "X-Timestamp:$ts\r\nContent-Type:application/json; charset=utf-8\r\n" +
                        "Path:speech.config\r\n\r\n" +
                        "{\"context\":{\"synthesis\":{\"audio\":{\"metadataoptions\":{" +
                        "\"sentenceBoundaryEnabled\":\"false\",\"wordBoundaryEnabled\":\"true\"}," +
                        "\"outputFormat\":\"$OUTPUT_FORMAT\"}}}}}\r\n"
                )
                webSocket.send(
                    "X-RequestId:$requestId\r\nContent-Type:application/ssml+xml\r\n" +
                        "X-Timestamp:${nowEdgeString()}\r\nPath:ssml\r\n\r\n" +
                        ssml(text, voice, pitch, rate, volume, style)
                )
            }

            override fun onMessage(webSocket: WebSocket, text: String) {
                when {
                    text.contains("audio.metadata") -> {
                        val idx = text.indexOf("\r\n\r\n")
                        if (idx >= 0) {
                            runCatching {
                                val arr = kotlinx.serialization.json.Json.parseToJsonElement(
                                    text.substring(idx + 4)
                                ) as kotlinx.serialization.json.JsonArray
                                for (m in arr) {
                                    val type = m.jsonObject["Metadata"]?.jsonObject?.get("Type")?.jsonPrimitive?.content
                                    if (type == "WordBoundary") {
                                        val d = m.jsonObject["Data"]!!.jsonObject
                                        val off = d["Offset"]!!.jsonPrimitive.long / 10000.0
                                        val dur = d["Duration"]!!.jsonPrimitive.long / 10000.0
                                        val t = d["text"]?.jsonObject?.get("Text")?.jsonPrimitive?.content ?: ""
                                        words.add(Word(off, dur, t))
                                    }
                                }
                            }
                        }
                    }

                    text.contains("Path:turn.end") && !ended -> {
                        ended = true
                        done.complete(Synthesis(audio.toByteArray(), words))
                    }

                    text.contains("Path:response") && text.contains("path:false") ->
                        if (!done.isCompleted) {
                            done.completeExceptionally(IllegalStateException("Edge-TTS отклонил запрос (неверный голос)"))
                        }
                }
            }

            override fun onMessage(webSocket: WebSocket, bytes: ByteString) {
                val b = bytes.toByteArray()
                if (b.size < 2) return
                val hl = ((b[0].toInt() and 0xff) shl 8) or (b[1].toInt() and 0xff)
                val from = 2 + hl + 2
                if (from <= b.size) audio.write(b, from, b.size - from)
            }

            override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
                if (!done.isCompleted) {
                    done.completeExceptionally(
                        IllegalStateException("Edge-TTS: сеть недоступна или сервер не ответил", t)
                    )
                }
            }
        })

        val watchdog = Thread {
            Thread.sleep(65_000)
            if (!done.isCompleted) {
                socket.close(1000, "timeout")
                done.completeExceptionally(IllegalStateException("Тайм-аут синтеза (проверьте интернет)"))
            }
        }.apply { isDaemon = true; start() }

        try {
            val res = done.await()
            res
        } finally {
            watchdog.interrupt()
            socket.close(1000, "done")
        }
    }
}

private val kotlinx.serialization.json.JsonElement.jsonObject
    get() = this as kotlinx.serialization.json.JsonObject

private val kotlinx.serialization.json.JsonObject.jsonArray
    get() = this["Metadata"] as? kotlinx.serialization.json.JsonArray ?: kotlinx.serialization.json.JsonArray(emptyList())

