    fun cast(langName: String): String {
        val head = if (langName.isEmpty()) "" else "Язык реплик: $langName. "
        return "Ты — режиссёр дубляжа манги/комикса. Определи, кто говорит каждую реплику. ${head}Правила:\n" +
