/** Нормализация имён и раздача голосов — порт js/cast.js. */
object CastPlanner {

    val NARRATOR = Defaults.NARRATOR

    private val NARRATOR_KEYS = setOf(
        "нарратор", "рассказчик", "автор", "закадровый", "текст", "narrator", "narrator voice",
        "off-screen", "offscreen", "ос", "s.e."
    )
    private val UNKNOWN_KEYS = setOf("?", "неизвестно", "неясно", "unknown", "none", "-", "—", "нет", "n/a")

    fun normName(s: String): String {
        var t = s.replace(Regex("[«»\"“”'`*_~]"), " ")
        t = t.replace(Regex("\\s+"), " ").trim()
        t = t.replace(Regex("[.!?,;:…]+$"), "")
        t = t.replace(Regex("\\s+"), " ").trim()
        return t.lowercase().replace('ё', 'е')
    }

    fun isNarrator(name: String): Boolean = normName(name) in NARRATOR_KEYS

    fun isUnknownName(name: String): Boolean = normName(name) in UNKNOWN_KEYS

    fun normGender(g: String): String {
        val s = g.lowercase().trim()
        return when {
            s in listOf("m", "male", "man", "masc", "муж", "м") -> "male"
            s in listOf("f", "female", "woman", "fem", "жен", "ж") -> "female"
            else -> "other"
        }
    }

    /** Результат раздачи: роль → голос и причина. */
    data class Cast(val voice: String, val reason: String)
    data class CastPlan(val casts: Map<String, Cast>, val reused: Int, val otherLang: Int)

    val REASON_TEXT = mapOf(
        "manual" to "вручную", "gender" to "по полу", "free" to "свободный",
        "other-lang" to "другой язык", "reused" to "повтор: голосов не хватило"
    )

    /**
     * Раздаёт голоса с учётом пола и языка, не трогая ручной выбор.
     * langPrefix — «ru», «en-US»…; narratorRoleId — роль закадрового голоса.
     */
    fun planCasts(
        roles: List<Role>,
        voices: List<VoiceCatalog.Voice>,
        langPrefix: String,
        manual: Set<String>,
        narratorRoleId: String?
    ): CastPlan {
        if (roles.isEmpty()) return CastPlan(emptyMap(), 0, 0)
        val langPool = voices.filter { it.lang.lowercase().startsWith(langPrefix.lowercase()) }
        val useLangPool = langPool.size >= roles.size
        val base = if (useLangPool) langPool else voices
        val used = HashSet<String>()
        roles.forEach { if (it.voice.isNotBlank()) used.add(it.voice) }
        val out = HashMap<String, Cast>()

        // 1) ручные и уже назначенные
        val pending = ArrayList<Role>()
        for (r in roles) {
            if (r.voice.isNotBlank() && (manual.contains(r.id) || manual.isEmpty())) {
                out[r.id] = Cast(r.voice, "manual")
            } else pending.add(r)
        }
        // 2) по полу
        for (r in pending) {
            val want = when (normGender(r.gender)) {
                "male" -> "m"
                "female" -> "f"
                else -> ""
            }
            if (r.id == narratorRoleId || want.isEmpty()) continue
            val free = base.firstOrNull { it.gender == want && !used.contains(it.id) }
            if (free != null) {
                used.add(free.id)
                out[r.id] = Cast(free.id, "gender")
            }
        }
        // 3) любой свободный из базового пула
        for (r in pending) {
            if (out.containsKey(r.id)) continue
            val free = base.firstOrNull { !used.contains(it.id) }
            if (free != null) {
                used.add(free.id)
                out[r.id] = Cast(free.id, if (useLangPool) "free" else "other-lang")
            }
        }
        // 4) повтор
        var reused = 0
        for (r in pending) {
            if (out.containsKey(r.id)) continue
            val v = base.firstOrNull()?.id ?: voices.firstOrNull()?.id ?: return CastPlan(out, reused, 0)
            reused++
            out[r.id] = Cast(v, "reused")
        }
        // причина должна отражать реальность
        var otherLang = 0
        for (r in roles) {
            val c = out[r.id] ?: continue
            if (c.reason != "manual" && c.reason != "reused") {
                val vlang = VoiceCatalog.byId(c.voice)?.lang ?: ""
                if (!vlang.lowercase().startsWith(langPrefix.lowercase())) {
                    out[r.id] = c.copy(reason = "other-lang")
                }
            }
            if (out[r.id]?.reason == "other-lang") otherLang++
        }
        return CastPlan(out, reused, otherLang)
    }

    // ---------- привязка нарезок клипа к репликам ----------

    data class TakePlan(val order: List<Int>, val unused: List<Int>, val missing: List<Int>)

    fun planTakes(lineDurs: List<Double>, segDurs: List<Double>, byDuration: Boolean): TakePlan {
        if (lineDurs.isEmpty() || segDurs.isEmpty()) return TakePlan(emptyList(), segDurs.indices.toList(), lineDurs.indices.toList())
        if (!byDuration) {
            val order = lineDurs.indices.map { it % segDurs.size }
            return TakePlan(order, emptyList(), if (lineDurs.size > segDurs.size) (segDurs.size until lineDurs.size).toList() else emptyList())
        }
        val li = lineDurs.indices.sortedBy { lineDurs[it] }
        val si = segDurs.indices.sortedBy { segDurs[it] }
        val order = IntArray(lineDurs.size) { -1 }
        var p = 0
        for (idx in li) {
            if (p >= si.size) break
            order[idx] = si[p]
            p++
        }
        return TakePlan(order.toList(), (p until segDurs.size).map { si[it] }, emptyList())
    }

    fun takeMismatch(a: Double, b: Double): Double = max(a / b, b / a)

    // ---------- сборка реплик по страницам ----------

    data class Row(val pageIndex: Int, val bubble: Bubble)

    fun allRows(pages: List<Page>): List<Row> =
        pages.flatMapIndexed { pi, p -> p.bubbles.map { Row(pi, it) } }

    fun lineDuration(b: Bubble): Double =
        b.audio?.duration?.takeIf { it > 0 } ?: Pcm.estimateSpeakDuration(b.text)
}

/** Планировщик озвучки: сопоставление ролей и реплик. */
object CastApply {

    data class Result(
        val roles: List<Role>,
        val bubblesByPage: Map<String, List<Bubble>>,
        val assigned: Int,
        val unnamed: Int,
        val unused: Int
    )

    fun mergeCharacters(
        existing: List<Role>,
        ai: List<AiTasks.AiCharacter>
    ): Triple<List<Role>, Map<String, Role>, Set<String>> {
        val roles = ArrayList(existing)
        val byName = HashMap<String, Role>()
        val taken = HashSet<String>()
        for (r in existing) {
            val k = CastPlanner.normName(r.name)
            if (k.isNotEmpty() && !byName.containsKey(k)) byName[k] = r
            if (CastPlanner.isNarrator(r.name)) taken.add(r.id)
        }
        val unused = existing.filter { !CastPlanner.isNarrator(it.name) && !byName.values.any { v -> v.id == it.id } }
        for (c in ai) {
            if (CastPlanner.isUnknownName(c.name)) continue
            val key = CastPlanner.normName(c.name)
            if (key.isEmpty() || byName.containsKey(key)) continue
            val free = existing.firstOrNull { !taken.contains(it.id) }
            val role = if (free != null) {
                taken.add(free.id)
                free.copy(
                    name = c.name, gender = CastPlanner.normGender(c.gender),
                    emoji = Defaults.emojiForGender(CastPlanner.normGender(c.gender))
                )
            } else {
                Role(
                    name = c.name, gender = CastPlanner.normGender(c.gender),
                    emoji = Defaults.emojiForGender(CastPlanner.normGender(c.gender)),
                    color = Defaults.roleColor(roles.size)
                ).also { taken.add(it.id) }
            }
            val idx = roles.indexOfFirst { it.id == role.id }
            if (idx >= 0) roles[idx] = role else roles.add(role)
            byName[key] = role
        }
        return Triple(roles, byName, unused.map { it.name }.toSet())
    }

    /** Сопоставляет имя говорящего с ролью: точное совпадение, потом префикс. */
    fun resolveSpeaker(speaker: String, speakers: Set<String>, narratorRoleId: String?): String {
        val s = speaker.trim()
        if (s.isEmpty() || CastPlanner.isUnknownName(s)) return ""
        if (CastPlanner.isNarrator(s) && narratorRoleId != null) return narratorRoleId
        if (speakers.contains(s)) return s
        val hit = speakers.firstOrNull { it.startsWith(s) || s.startsWith(it) }
        return hit ?: ""
    }

    fun durationStats(bubbles: List<Bubble>): Triple<Int, Int, Int> {
        val withRole = bubbles.count { it.roleId.isNotBlank() }
        val voiced = bubbles.count { it.audio != null }
        return Triple(bubbles.size, withRole, voiced)
    }

    fun minMax(durs: List<Double>): Pair<Double, Double> =
        if (durs.isEmpty()) 0.0 to 0.0 else durs.min() to durs.max()

    fun clampDur(d: Double): Double = min(14.0, max(1.1, d))
}

package com.voicecomic.app.render

import com.voicecomic.app.audio.Pcm
import com.voicecomic.app.data.Bubble
import com.voicecomic.app.data.Page
import com.voicecomic.app.data.Role
import kotlin.math.max
import kotlin.math.min

data class Item(
    val page: Page,
    val pageIndex: Int,
    val bubble: Bubble?,
    val t: Double,
    val dur: Double,
    val kind: String // line | idle
)

data class Cam(val sx: Float, val sy: Float, val sw: Float, val sh: Float, val zoom: Float)

object Timeline {

    /** Пороги обрезки тишины для озвучки (единая точка правды, как TRIM в engine.js). */
    const val TRIM_THRESHOLD = 0.012
    const val TRIM_MARGIN = 0.05
    const val TRIM_MIN_DUR = 0.25

    fun build(pages: List<Page>, gapMs: Int): Pair<List<Item>, Double> {
        val gap = (gapMs / 1000.0)
        val items = ArrayList<Item>()
        var t = 0.0
        for ((pi, page) in pages.withIndex()) {
            if (page.bubbles.isEmpty()) {
                items.add(Item(page, pi, null, t, 1.8, "idle"))
                t += 1.8
                continue
            }
            t += 0.55
            for ((bi, b) in page.bubbles.withIndex()) {
                t += if (bi == 0) 0.25 else gap
                val dur = b.audio?.duration?.takeIf { it > 0 } ?: Pcm.estimateSpeakDuration(b.text)
                items.add(Item(page, pi, b, t, dur, "line"))
                t += dur
                t += gap * 0.6
            }
            t += 0.5
        }
        return items to (t + 0.9)
    }

    fun roleGain(role: Role?): Float {
        if (role == null) return 1f
        val pct = if (role.volumeNum in 1..1000) role.volumeNum.toDouble() else run {
            val m = Regex("^\\s*([+-]?\\d+(?:\\.\\d+)?)\\s*%\\s*$").find(role.volume)
            val v = m?.groupValues?.get(1)?.toDoubleOrNull() ?: 0.0
            100 + v
        }
        return (pct / 100.0).coerceIn(0.0, 2.0).toFloat()
    }

    fun bubbleHasBox(b: Bubble, page: Page): Boolean {
        if (page.bubblesHaveBoxes.not()) return false
        return b.hasBox()
    }

    private fun smooth(a: Double): Double = a * a * (3 - 2 * a)

    private fun clampV(v: Double, lo: Double, hi: Double) = min(hi, max(lo, v))

    /** Камера Ken Burns: возвращает вырезку исходника в пикселях страницы. */
    fun cameraFor(item: Item, clock: Double, cw: Int, ch: Int, zoomMode: String): Cam {
        val pw = (if (item.page.w > 0) item.page.w else 1).toDouble()
        val ph = (if (item.page.h > 0) item.page.h else 1).toDouble()
        val cover = max(cw / pw, ch / ph)
        val b = item.bubble
        val hasBox = b != null && bubbleHasBox(b, item.page)

        if (hasBox && zoomMode != "none") {
            val bcx = b!!.x!! + b.w!! / 2
            val bcy = b.y!! + b.h!! / 2
            val crop = when (zoomMode) {
                "pan" -> cover * 1.15
                else -> {
                    val prog = smooth(min(1.0, max(0.0, (clock - item.t) / item.dur)))
                    val zoomFrom = cover * 1.2
                    val zoomTo = cover * max(
                        1.0,
                        min(2.6, max(cw / (b.w!! * 1.3 + 1), ch / (b.h!! * 1.3 + 1)))
                    )
                    zoomFrom + (zoomTo - zoomFrom) * prog
                }
            }
            val vw = cw / crop
            val vh = ch / crop
            val sx = clampV(bcx - vw / 2, 0.0, max(0.0, pw - vw))
            val sy = clampV(bcy - vh / 2, 0.0, max(0.0, ph - vh))
            return Cam(sx.toFloat(), sy.toFloat(), vw.toFloat(), vh.toFloat(), crop.toFloat())
        }

        val z = if (zoomMode == "none") cover else cover * 1.12
        val vw = cw / z
        val vh = ch / z
        var sx = (pw - vw) / 2
        var sy = (ph - vh) / 2
        if (zoomMode == "pan" || zoomMode == "smart") {
            val phase = smooth(((clock - item.t) / (if (item.dur > 0) item.dur else 1.0)).coerceIn(0.0, 1.0))
            if (ph > pw * 1.2) {
                val r = max(0.0, ph - vh)
                sy = clampV((phase - 0.5) * 2 * r * 0.6 + ph / 2 - vh / 2, 0.0, r)
            } else {
                val r = max(0.0, pw - vw)
                sx = clampV((phase - 0.5) * 2 * r * 0.8 + pw / 2 - vw / 2, 0.0, r)
            }
        }
        sx = clampV(sx, 0.0, max(0.0, pw - vw))
        sy = clampV(sy, 0.0, max(0.0, ph - vh))
        return Cam(sx.toFloat(), sy.toFloat(), vw.toFloat(), vh.toFloat(), z.toFloat())
    }

    fun currentItem(items: List<Item>, clock: Double): Item? {
        if (items.isEmpty()) return null
        var cur = items[0]
        for (it in items) {
            if (it.t <= clock) cur = it else break
        }
        return cur
    }

    fun resolveSize(res: String, pages: List<Page>): Pair<Int, Int> {
        if (res != "auto") {
            val p = res.split("x")
            return (p.getOrNull(0)?.toIntOrNull() ?: 1080) to (p.getOrNull(1)?.toIntOrNull() ?: 1920)
        }
        val p0 = pages.firstOrNull()
        val ratio = if (p0 != null && p0.h > 0 && p0.w > 0) p0.h.toDouble() / p0.w else 16.0 / 9
        val h = 1080
        var w = Math.round(h / ratio)
        w -= w % 2
        return w.coerceAtLeast(2) to h
    }
}

package com.voicecomic.app.render

import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.Rect
import android.graphics.RectF
import android.graphics.Typeface
import com.voicecomic.app.data.Bubble
import com.voicecomic.app.data.Role
import com.voicecomic.app.data.Settings
import kotlin.math.max
import kotlin.math.min

/**
 * Отрисовка кадра: вырезка страницы по камере + пузырь или субтитры.
 * Порт drawCaption/cameraFor из engine.js на android.graphics.
 */
class FrameRenderer(val outW: Int, val outH: Int) {

    private val src = Rect()
    private val dst = Rect(0, 0, outW, outH)
    private val rect = RectF()
    private val imagePaint = Paint(Paint.FILTER_BITMAP_FLAG or Paint.ANTI_ALIAS_FLAG)
    private val fill = Paint(Paint.ANTI_ALIAS_FLAG)
    private val stroke = Paint(Paint.ANTI_ALIAS_FLAG).apply { style = Paint.Style.STROKE }
    private val text = Paint(Paint.ANTI_ALIAS_FLAG).apply { typeface = Typeface.create("sans-serif", Typeface.NORMAL) }

    fun drawFrame(canvas: Canvas, page: android.graphics.Bitmap?, item: Item, clock: Double, settings: Settings, zoom: String) {
        canvas.drawColor(Color.BLACK)
        val cam = Timeline.cameraFor(item, clock, outW, outH, zoom)
        if (page != null) {
            val pw = if (item.page.w > 0) item.page.w else page.width
            val ph = if (item.page.h > 0) item.page.h else page.height
            src.set(
                cam.sx.toInt().coerceIn(0, max(1, pw - 1)),
                cam.sy.toInt().coerceIn(0, max(1, ph - 1)),
                (cam.sx + cam.sw).toInt().coerceIn(1, pw),
                (cam.sy + cam.sh).toInt().coerceIn(1, ph)
            )
            if (src.width() > 0 && src.height() > 0) {
                canvas.drawBitmap(page, src, dst, imagePaint)
            }
        }
        val role = item.bubble?.let { b -> roleFor(item, b) }
        drawCaption(canvas, item, settings, role)
    }

    var roleResolver: (Item) -> Role? = { null }

    private fun roleFor(item: Item, b: Bubble): Role? = roleResolver(item)

    private fun drawCaption(canvas: Canvas, item: Item, settings: Settings, role: Role?) {
        val b = item.bubble ?: return
        val hasBox = Timeline.bubbleHasBox(b, item.page)
        val mode = if (hasBox) (settings.caption.ifEmpty { "bubble" }) else (if (settings.caption == "none") "none" else "sub")
        if (mode == "none") return

        val main: String
        val second: String
        when (settings.biling) {
            "tr" -> {
                main = b.tr.ifBlank { b.text }
                second = if (b.tr.isNotBlank()) b.text else ""
            }

            "origtr" -> {
                main = b.text
                second = b.tr
            }

            else -> {
                main = b.text
                second = ""
            }
        }
        if (mode == "bubble" && hasBox) drawBubble(canvas, b, main, role, settings)
        else drawSubtitle(canvas, main, second, role)
    }

    private fun measureM(size: Float): Float = run {
        text.textSize = size
        text.measureText("М")
    }

    private fun drawBubble(canvas: Canvas, b: Bubble, shown: String, role: Role?, settings: Settings) {
        val camScaleX = outW.toFloat() / 1f // камера уже учтена в координатах страницы
        val x = b.x!! * camScaleX
        val y = b.y!!
        val w = b.w!!
        val h = b.h!!
        fill.color = Color.argb(235, 255, 255, 255)
        rect.set(x, y, x + w, y + h)
        val r = min(10f, min(w / 2, h / 2))
        canvas.drawRoundRect(rect, r, r, fill)
        stroke.color = parseColor(role?.color ?: "#555555")
        stroke.strokeWidth = max(2f, min(6f, outW / 300f))
        canvas.drawRoundRect(rect, r, r, stroke)

        val pad = max(4f, w * 0.04f)
        val size = max(13f, w / 14f)
        text.textSize = size
        text.color = Color.parseColor("#111111")
        text.typeface = Typeface.create("sans-serif", Typeface.BOLD)
        val lineH = measureM(size) * 1.4f
        val maxLines = max(1, ((h - 2 * pad) / lineH).toInt())
        val lines = wrap(shown, w - 2 * pad, size)
        canvas.save()
        canvas.clipRect(x, y, x + w, y + h)
        lines.take(maxLines).forEachIndexed { i, ln ->
            canvas.drawText(ln, x + pad, y + pad + lineH * (i + 0.8f), text)
        }
        canvas.restore()

        if (role != null) {
            val label = (role.emoji + " " + role.name).trim()
            text.textSize = max(11f, outW / 130f)
            text.typeface = Typeface.create("sans-serif", Typeface.BOLD)
            text.color = parseColor(role.color)
            canvas.drawText(label, x + pad, max(2f, y - measureM(text.textSize) * 1.3f), text)
        }
    }

    private fun drawSubtitle(canvas: Canvas, main: String, second: String, role: Role?) {
        val lineH = max(26f, outH * 0.055f)
        val bandH = lineH * (if (second.isNotEmpty()) 2.1f else 1.25f) + 26f
        val top = outH - bandH
        fill.color = Color.argb(140, 0, 0, 0)
        canvas.drawRect(0f, top, outW.toFloat(), outH.toFloat(), fill)
        val fs = max(18f, outH * 0.042f)

        if (role != null) {
            text.typeface = Typeface.create("sans-serif", Typeface.BOLD)
            text.textSize = fs
            text.color = parseColor(role.color)
            val label = (role.emoji + " " + role.name).trim()
            canvas.drawText(label, outW / 2f - measureCentred(label, fs), top + 14f + fs * 0.6f, text)
        }
        text.typeface = Typeface.create("sans-serif", Typeface.BOLD)
        text.textSize = fs
        text.color = Color.WHITE
        val maxW = outW * 0.92f
        val lines = wrap(main, maxW, fs)
        var y = outH - (if (second.isNotEmpty()) bandH * 0.62f else bandH * 0.55f)
        lines.take(3).forEach { ln ->
            canvas.drawText(ln, outW / 2f - measureCentred(ln, fs), y, text)
            y += fs * 1.25f
        }
        if (second.isNotEmpty()) {
            text.typeface = Typeface.create("sans-serif", Typeface.NORMAL)
            text.textSize = fs * 0.72f
            text.color = Color.parseColor("#cfd8e8")
            canvas.drawText(
                wrap(second, maxW, text.textSize).take(2).joinToString(" "),
                outW / 2f - measureCentred(second, text.textSize),
                outH - lineH + text.textSize,
                text
            )
        }
    }

    private fun measureCentred(s: String, size: Float): Float {
        text.textSize = size
        return text.measureText(s) / 2f
    }

    /** Жадный перенос по пробелам — как wrapLines в util.js. */
    fun wrap(s: String, maxW: Float, size: Float): List<String> {
        text.textSize = size
        val out = ArrayList<String>()
        for (paragraph in s.split('\n')) {
            var line = StringBuilder()
            for (word in paragraph.split(Regex("\\s+"))) {
                if (word.isEmpty()) continue
                val probe = if (line.isEmpty()) word else "$line $word"
                if (text.measureText(probe) > maxW && line.isNotEmpty()) {
                    out.add(line.toString())
                    line = StringBuilder(word)
                } else {
                    line = StringBuilder(probe)
                }
            }
            if (line.isNotEmpty()) out.add(line.toString())
        }
        return out
    }

    companion object {
        fun parseColor(hex: String): Int = runCatching { Color.parseColor(hex) }.getOrDefault(Color.GRAY)
    }
}

