package com.voicecomic.app.render

import com.voicecomic.app.audio.Pcm
import com.voicecomic.app.data.Project
import com.voicecomic.app.data.Role
import com.voicecomic.app.data.Settings
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File
import kotlin.math.max
import kotlin.math.min

/**
 * Сведение дорожки в один буфер 44.1 кГц моно — порт renderAudioTrack из engine.js.
 * Возвращает FloatArray PCM.
 */
class AudioMixer(
    private val projectId: String,
    private val resolve: (String) -> File
) {

    class Mixed(val pcm: FloatArray, val sr: Int, val duration: Double, val voiced: Int)

    private fun mixAdd(out: FloatArray, offsetSec: Double, vol: Float, sr: Int) {
        val i0 = (offsetSec * sr).toInt()
        if (i0 >= out.size) return
        val n = min(out.size - i0, sr.toLong().toInt())
        for (k in 0 until n) out[i0 + k] += src!![k] * vol
    }

    private var src: FloatArray? = null

    suspend fun render(
        items: List<Item>,
        total: Double,
        project: Project,
        settings: Settings,
        onProgress: (Double, String) -> Unit
    ): Mixed = withContext(Dispatchers.IO) {
        val sr = Pcm.MIX_RATE
        val frames = Pcm.framesFor(total, sr)
        val out = FloatArray(max(0, frames))
        val roleById = project.roles.associateBy { it.id }
        var voiced = 0

        for ((n, it) in items.withIndex()) {
            val b = it.bubble ?: continue
            val audio = b.audio ?: continue
            val f = resolve(audio.file)
            if (!f.exists()) continue
            val raw = Pcm.readWav(f) ?: continue
            var (samples, fileSr) = raw
            var offsetSec = it.t
            var dur = it.dur
            if (audio.noTrim) {
                dur = samples.size.toDouble() / fileSr
            } else {
                val trim = Pcm.trimSilence(samples, fileSr, Timeline.TRIM_THRESHOLD, Timeline.TRIM_MARGIN)
                if (trim.end > trim.start) {
                    samples = samples.copyOfRange(trim.start, trim.end)
                    offsetSec = it.t + trim.start.toDouble() / fileSr
                    dur = max(Timeline.TRIM_MIN_DUR, (trim.end - trim.start).toDouble() / fileSr)
                } else dur = Timeline.TRIM_MIN_DUR
            }
            if (fileSr != sr) samples = Pcm.resampleLinear(samples, fileSr, sr)
            val gain = Timeline.roleGain(roleById[b.roleId])
            src = samples
            mixAdd(out, offsetSec, gain, sr)
            src = null
            voiced++
            if (n % 5 == 0) onProgress(0.5 * (n + 1) / items.size, "Сведение речи")
        }

        if (settings.music.isNotBlank()) {
            val mf = resolve(settings.music)
            if (mf.exists()) {
                Pcm.readWav(mf)?.let { (mSamples, mSr) ->
                    val music = if (mSr != sr) Pcm.resampleLinear(mSamples, mSr, sr) else mSamples
                    val step = if (music.isNotEmpty()) music.size.toDouble() / sr else total
                    if (step > 0) {
                        var pos = 0.0
                        var guard = 0
                        val vol = (settings.mvol / 100.0 * 0.6).toFloat()
                        while (pos < total && guard++ < 10000) {
                            src = music
                            mixAdd(out, pos, vol, sr)
                            src = null
                            pos += step
                        }
                    }
                }
            }
        }

        for (i in out.indices) out[i] = out[i].coerceIn(-1f, 1f)
        onProgress(0.9, "Аудио готово")
        Mixed(out, sr, total, voiced)
    }

    /** Список файлов озвучки, участвующих в миксе (для оценок и отладки). */
    fun speechFiles(items: List<Item>): List<File> = items.mapNotNull { it.bubble?.audio?.file }
        .filter { it.isNotBlank() }
        .map { resolve(it) }
        .filter { it.exists() }
}

fun roleFor(project: Project, roleId: String): Role? = project.roles.firstOrNull { it.id == roleId }

package com.voicecomic.app.render

import android.graphics.Bitmap
import android.graphics.Canvas
import android.media.MediaCodec
import android.media.MediaCodecInfo
import android.media.MediaFormat
import android.media.MediaMuxer
import android.opengl.EGL14
import android.opengl.EGLConfig
import android.opengl.EGLContext
import android.opengl.EGLDisplay
import android.opengl.EGLSurface
import android.opengl.GLES20
import android.view.Surface
import com.voicecomic.app.audio.Pcm
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.withContext
import java.io.File
import java.nio.ByteBuffer

/**
 * Поверхность ввода MediaCodec: рисует готовый Bitmap кадра через EGL прямо
 * в кодировщик H.264. Замена MediaRecorder + canvas.captureStream из веб-версии.
 */
class CodecSurface(codec: MediaCodec, private val width: Int, private val height: Int) {

    private var display: EGLDisplay = EGL14.EGL_NO_DISPLAY
    private var context: EGLContext = EGL14.EGL_NO_CONTEXT
    private var surface: EGLSurface = EGL14.EGL_NO_SURFACE
    private var program = 0
    private var aPos = 0
    private var aTex = 0
    private var uMvp = 0
    private var uTex = 0
    private var texture = 0

    fun start() {
        display = EGL14.eglGetDisplay(EGL14.EGL_DEFAULT_DISPLAY)
        val version = IntArray(2)
        EGL14.eglInitialize(display, version, 0, version, 1)
        val attrs = intArrayOf(EGL14.EGL_RED_SIZE, 8, EGL14.EGL_GREEN_SIZE, 8, EGL14.EGL_BLUE_SIZE, 8,
            EGL14.EGL_ALPHA_SIZE, 8, EGL14.EGL_RENDERABLE_TYPE, EGL14.EGL_OPENGL_ES2_BIT, 0x3033, 1, 0x0000)
        val configs = arrayOfNulls<EGLConfig>(1)
        val num = IntArray(1)
        EGL14.eglChooseConfig(display, attrs, 0, configs, 0, 1, num, 0)
        val config = configs[0] ?: throw IllegalStateException("EGL: нет конфигурации")
        context = EGL14.eglCreateContext(display, config, EGL14.EGL_NO_CONTEXT, intArrayOf(EGL14.EGL_CONTEXT_CLIENT_VERSION, 2, 0x3098), 0)
        val input: Surface = codec.createInputSurface()
        surface = EGL14.eglCreateWindowSurface(display, config, input, intArrayOf(EGL14.EGL_NONE), 0)
        EGL14.eglMakeCurrent(display, surface, surface, context)
        GLES20.glViewport(0, 0, width, height)
        buildProgram()
    }

    private fun buildProgram() {
        val vs = compile(GLES20.GL_VERTEX_SHADER, VERT)
        val fs = compile(GLES20.GL_FRAGMENT_SHADER, FRAG)
        program = GLES20.glCreateProgram()
        GLES20.glAttachShader(program, vs)
        GLES20.glAttachShader(program, fs)
        GLES20.glLinkProgram(program)
        GLES20.glUseProgram(program)
        aPos = GLES20.glGetAttribLocation(program, "aPos")
        aTex = GLES20.glGetAttribLocation(program, "aTex")
        uMvp = GLES20.glGetUniformLocation(program, "uMvp")
        uTex = GLES20.glGetUniformLocation(program, "uTex")
        texture = GLES20.glGenTextures(1, IntArray(1), 0)
        GLES20.glBindTexture(GLES20.GL_TEXTURE_2D, texture)
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_MIN_FILTER, GLES20.GL_LINEAR)
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_MAG_FILTER, GLES20.GL_LINEAR)
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_WRAP_S, GLES20.GL_CLAMP_TO_EDGE)
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_WRAP_T, GLES20.GL_CLAMP_TO_EDGE)
        val vp = floatArrayOf(-1f, -1f, 1f, -1f, -1f, 1f, 1f, 1f)
        val buf = java.nio.ByteBuffer.allocateDirect(vp.size * 4).order(java.nio.ByteOrder.nativeOrder()).asFloatBuffer()
        buf.put(vp).position(0)
        GLES20.glVertexAttribPointer(aPos, 2, GLES20.GL_FLOAT, false, 0, buf)
        GLES20.glEnableVertexAttribArray(aPos)
        val uv = floatArrayOf(0f, 1f, 1f, 1f, 0f, 0f, 1f, 0f)
        val ub = java.nio.ByteBuffer.allocateDirect(uv.size * 4).order(java.nio.ByteOrder.nativeOrder()).asFloatBuffer()
        ub.put(uv).position(0)
        GLES20.glVertexAttribPointer(aTex, 2, GLES20.GL_FLOAT, false, 0, ub)
        GLES20.glEnableVertexAttribArray(aTex)
    }

    private fun compile(type: Int, src: String): Int {
        val shader = GLES20.glCreateShader(type)
        GLES20.glShaderSource(shader, src)
        GLES20.glCompileShader(shader)
        return shader
    }

    fun draw(bitmap: Bitmap, ptsUs: Long) {
        GLES20.glClearColor(0f, 0f, 0f, 1f)
        GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT)
        val buf = java.nio.ByteBuffer.allocateDirect(bitmap.width * bitmap.height * 4)
            .order(java.nio.ByteOrder.nativeOrder())
        bitmap.copyPixelsToBuffer(buf)
        buf.position(0)
        GLES20.glBindTexture(GLES20.GL_TEXTURE_2D, texture)
        GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D, 0, GLES20.GL_RGBA, bitmap.width, bitmap.height, 0,
            GLES20.GL_RGBA, GLES20.GL_UNSIGNED_BYTE, buf)
        GLES20.glUniformMatrix4fv(uMvp, 1, false, IDENTITY, 0)
        GLES20.glUniform1i(uTex, 0)
        GLES20.glDrawArrays(GLES20.GL_TRIANGLE_STRIP, 0, 4)
        EGLExt.eglPresentationTimeANDROID(display, surface, ptsUs)
        EGL14.eglSwapBuffers(display, surface)
    }

    fun release() {
        if (display != EGL14.EGL_NO_DISPLAY) {
            EGL14.eglMakeCurrent(display, EGL14.EGL_NO_SURFACE, EGL14.EGL_NO_SURFACE, EGL14.EGL_NO_CONTEXT)
            EGL14.eglDestroySurface(display, surface)
            EGL14.eglDestroyContext(display, context)
            EGL14.eglReleaseThread()
            EGL14.eglTerminate(display)
        }
        display = EGL14.EGL_NO_DISPLAY
        context = EGL14.EGL_NO_CONTEXT
        surface = EGL14.EGL_NO_SURFACE
    }

    private object EGLExt {
        fun eglPresentationTimeANDROID(dpy: EGLDisplay, s: EGLSurface, pts: Long) {
            android.opengl.EGLExt.eglPresentationTimeANDROID(dpy, s, pts)
        }
    }

    companion object {
        private val IDENTITY = floatArrayOf(1f, 0f, 0f, 0f, 0f, 1f, 0f, 0f, 0f, 0f, 1f, 0f, 0f, 0f, 0f, 1f)
        private const val VERT = """
            attribute vec4 aPos; attribute vec2 aTex; uniform mat4 uMvp; varying vec2 vTex;
            void main(){ gl_Position = uMvp * aPos; vTex = aTex; }
        """
        private const val FRAG = """
            precision mediump float; varying vec2 vTex; uniform sampler2D uTex;
            void main(){ gl_FragColor = texture2D(uTex, vTex); }
        """
    }
}

/**
 * Экспорт MP4: H.264 через MediaCodec + AAC через MediaCodec, сборка MediaMuxer'ом.
 * Потоки кодируются во временные файлы и муксируются в конце — так не нужен общий
 * поток записи в два трека.
 */
class VideoExporter {

    class Progress(val frac: Double, val message: String)

    /**
     * frameAt(i, tSeconds) должен вернуть Bitmap кадра или null (кадр пропускается).
     */
    suspend fun exportMp4(
        out: File,
        width: Int,
        height: Int,
        fps: Int,
        totalSeconds: Double,
        audio: ShortArray?,
        audioSr: Int,
        frameAt: suspend (i: Int, t: Double) -> Bitmap?
    ): File = withContext(Dispatchers.IO) {
        out.parentFile?.mkdirs()
        val totalFrames = ((totalSeconds * fps).toInt() + 1).coerceAtLeast(1)
        val h264 = File(out.absolutePath + ".h264")
        val aac = File(out.absolutePath + ".aac")
        try {
            encodeVideo(h264, width, height, fps, totalFrames, frameAt)
            if (audio != null && audio.isNotEmpty()) encodeAudio(aac, audio, audioSr)
            mux(out, h264, if (aac.exists() && aac.length() > 0) aac else null, fps)
            out
        } finally {
            h264.delete()
            aac.delete()
        }
    }

    private suspend fun encodeVideo(
        file: File,
        width: Int,
        height: Int,
        fps: Int,
        totalFrames: Int,
        frameAt: suspend (i: Int, t: Double) -> Bitmap?
    ) {
        val format = MediaFormat.createVideoFormat("video/avc", width, height).apply {
            setInteger(MediaFormat.KEY_COLOR_FORMAT, MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface)
            setInteger(MediaFormat.KEY_BIT_RATE, (width * height * fps * 0.14).toInt().coerceIn(2_000_000, 16_000_000))
            setInteger(MediaFormat.KEY_FRAME_RATE, fps)
            setInteger(MediaFormat.KEY_I_FRAME_INTERVAL, 2)
        }
        val codec = MediaCodec.createEncoderByType("video/avc")
        codec.configure(format, null, null, MediaCodec.CONFIGURE_FLAG_ENCODE)
        val egl = CodecSurface(codec, width, height)
        codec.start()
        egl.start()
        val info = MediaCodec.BufferInfo()
        val done = java.util.concurrent.atomic.AtomicBoolean(false)
        var framesSent = 0
        var framesDone = 0
        val out = file.outputStream()
        try {
            while (framesDone < totalFrames) {
                if (framesSent < totalFrames) {
                    val bmp = frameAt(framesSent, framesSent.toDouble() / fps)
                    if (bmp != null) {
                        egl.draw(bmp, framesSent * 1_000_000L / fps)
                        framesSent++
                    }
                    bmp?.recycle()
                }
                when (val idx = codec.dequeueOutputBuffer(info, if (framesSent >= totalFrames) 10_000L else 0L)) {
                    MediaCodec.INFO_TRY_AGAIN_LATER -> if (framesSent >= totalFrames) {
                        // ждём дренирования
                    } else if (!done.get()) Unit
                    MediaCodec.INFO_OUTPUT_FORMAT_CHANGED -> Unit
                    else -> {
                        if (idx >= 0) {
                            val buf: ByteBuffer = codec.getOutputBuffer(idx)!!
                            if (info.flags and MediaCodec.BUFFER_FLAG_CODEC_CONFIG != 0) {
                                info.size = 0
                            }
                            if (info.size > 0) {
                                val data = ByteArray(info.size)
                                buf.position(info.offset)
                                buf.limit(info.offset + info.size)
                                buf.get(data)
                                out.write(data)
                                framesDone++
                            }
                            done.set(info.flags and MediaCodec.BUFFER_FLAG_END_OF_STREAM != 0)
                            codec.releaseOutputBuffer(idx, false)
                            if (done.get()) break
                        }
                    }
                }
            }
        } finally {
            runCatching { egl.release() }
            runCatching { codec.stop() }
            runCatching { codec.release() }
            out.flush()
            out.close()
        }
    }

    private fun encodeAudio(file: File, pcm: ShortArray, sr: Int) {
        val ch = 1
        val bitRate = 128_000
        val format = MediaFormat.createAudioFormat("audio/mp4a-latm", sr, ch).apply {
            setInteger(MediaFormat.KEY_AAC_PROFILE, MediaCodecInfo.CodecProfileLevel.AACObjectLC)
            setInteger(MediaFormat.KEY_BIT_RATE, bitRate)
            setInteger(MediaFormat.KEY_MAX_INPUT_SIZE, 16 * 1024)
        }
        val codec = MediaCodec.createEncoderByType("audio/mp4a-latm")
        codec.configure(format, null, null, MediaCodec.CONFIGURE_FLAG_ENCODE)
        codec.start()
        val info = MediaCodec.BufferInfo()
        var idx = 0
        var pts = 0L
        val total = pcm.size * 2L / ch
        file.outputStream().use { out ->
            while (true) {
                val inIdx = codec.dequeueInputBuffer(10_000)
                if (inIdx >= 0) {
                    val buf = codec.getInputBuffer(inIdx)!!
                    buf.clear()
                    val n = minOf(buf.capacity() / 2, pcm.size - idx)
                    val bytes = ByteArray(n * 2)
                    for (i in 0 until n) {
                        val v = pcm[idx + i].toInt()
                        bytes[i * 2] = (v and 0xff).toByte()
                        bytes[i * 2 + 1] = ((v shr 8) and 0xff).toByte()
                    }
                    val ptsUs = pts * 1_000_000L / sr
                    if (n > 0) {
                        buf.put(bytes)
                        codec.queueInputBuffer(inIdx, 0, bytes.size, ptsUs, 0)
                        pts += n
                        idx += n
                    } else {
                        codec.queueInputBuffer(inIdx, 0, 0, pts * 1_000_000L / sr, MediaCodec.BUFFER_FLAG_END_OF_STREAM)
                    }
                }
                val outIdx = codec.dequeueOutputBuffer(info, 10_000)
                if (outIdx >= 0) {
                    val buf = codec.getOutputBuffer(outIdx)!!
                    if (info.flags and MediaCodec.BUFFER_FLAG_CODEC_CONFIG != 0) info.size = 0
                    if (info.size > 0) {
                        val data = ByteArray(info.size)
                        buf.position(info.offset)
                        buf.get(data)
                        out.write(data)
                    }
                    codec.releaseOutputBuffer(outIdx, false)
                    if (info.flags and MediaCodec.BUFFER_FLAG_END_OF_STREAM != 0) break
                }
                if (idx >= pcm.size && inIdx < 0) {
                    // страховка от зависания
                    val st = codec.dequeueOutputBuffer(info, 0)
                    if (st < 0) break
                }
            }
        }
        runCatching { codec.stop() }
        runCatching { codec.release() }
    }

    /** Конвертирует Annex-B в AVCC и собирает MP4. */
    private fun mux(out: File, h264: File, aac: File?, fps: Int) {
        val muxer = MediaMuxer(out.absolutePath, MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4)
        val videoSamples = readAnnexB(h264)
        val videoTrack = muxer.addTrack(
            MediaFormat.createVideoFormat("video/avc", 0, 0).apply {
                setInteger(MediaFormat.KEY_MIME, "video/avc")
            }
        )
        var audioTrack = -1
        if (aac != null) {
            audioTrack = muxer.addTrack(
                MediaFormat.createAudioFormat("audio/mp4a-latm", 44100, 1).apply {
                    setInteger(MediaFormat.KEY_MIME, "audio/mp4a-latm")
                    setInteger(MediaFormat.KEY_AAC_PROFILE, MediaCodecInfo.CodecProfileProfile.AACObjectLC)
                }
            )
        }
        muxer.start()
        val info = MediaCodec.BufferInfo()
        val bytes = fileBytes(out.parentFile!!.resolve(".muxbuf"), videoSamples.size * 2 + 1024)
        bytes.clear()
        var offset = 0
        val (samples, sizes) = videoSamples
        for (i in samples.indices) {
            val len = sizes[i]
            bytes.putInt(len)
            bytes.put(samples[i], 0, len)
            info.offset = offset
            info.size = len + 4
            info.presentationTimeUs = i * 1_000_000L / fps
            info.flags = if (i % (fps * 2) == 0) MediaCodec.BUFFER_FLAG_KEY_FRAME else 0
            muxer.writeSampleData(videoTrack, bytes, info)
            offset += info.size
        }
        if (audioTrack >= 0 && aac != null) {
            val a = aac.readBytes()
            info.offset = 0
            info.size = a.size
            info.presentationTimeUs = 0
            info.flags = MediaCodec.BUFFER_FLAG_KEY_FRAME
            muxer.writeSampleData(audioTrack, ByteBuffer.wrap(a), info)
        }
        muxer.stop()
        muxer.release()
        File(out.parentFile!!.resolve(".muxbuf")).delete()
    }

    private fun fileBytes(tmp: File, size: Int): ByteBuffer {
        tmp.delete()
        return java.nio.ByteBuffer.allocateDirect(size.coerceAtLeast(1024))
    }

    /** Возвращает список AVCC-семплов (без SPS/PPS) и их размеры. */
    private fun readAnnexB(file: File): Pair<Array<ByteArray>, IntArray> {
        val data = file.readBytes()
        val nals = ArrayList<ByteArray>()
        var i = 0
        var start = -1
        while (i + 3 < data.size) {
            if (data[i] == 0.toByte() && data[i + 1] == 0.toByte() && data[i + 2] == 0.toByte() && data[i + 3] == 1.toByte()) {
                if (start >= 0) nals.add(data.copyOfRange(start, i))
                start = i + 4
                i += 4
            } else i++
        }
        if (start in 0 until data.size) nals.add(data.copyOfRange(start, data.size))
        val samples = ArrayList<ByteArray>()
        val sizes = ArrayList<Int>()
        for (n in nals) {
            if (n.isEmpty()) continue
            val type = n[0].toInt() and 0x1f
            if (type == 1 || type == 5) {
                samples.add(n)
                sizes.add(n.size)
            }
        }
        return samples to sizes.toIntArray()
    }

    /** Только звук: WAV + M4A (AAC). */
    suspend fun exportAudio(
        wavOut: File,
        m4aOut: File,
        pcm: ShortArray,
        sr: Int
    ): Pair<File, File> = withContext(Dispatchers.IO) {
        Pcm.writeWav(wavOut, pcm, sr)
        val aac = File(wavOut.absolutePath + ".aac")
        try {
            encodeAudio(aac, pcm, sr)
            val muxer = MediaMuxer(m4aOut.absolutePath, MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4)
            val track = muxer.addTrack(
                MediaFormat.createAudioFormat("audio/mp4a-latm", sr, 1).apply {
                    setInteger(MediaFormat.KEY_MIME, "audio/mp4a-latm")
                }
            )
            muxer.start()
            val a = aac.readBytes()
            val info = MediaCodec.BufferInfo()
            info.offset = 0
            info.size = a.size
            info.presentationTimeUs = 0
            info.flags = MediaCodec.BUFFER_FLAG_KEY_FRAME
            muxer.writeSampleData(track, ByteBuffer.wrap(a), info)
            muxer.stop()
            muxer.release()
        } finally {
            aac.delete()
        }
        wavOut to m4aOut
    }
}

private fun minOf(a: Int, b: Int) = if (a < b) a else b

