/* ================================================================
 * Настройки: поля и проект
 * ================================================================ */
/* Слушатели полей настроек вешаются ровно один раз за сессию: bindSettings()
 * зовётся повторно при импорте проекта и при сбросе, и без этого га каждый
 * обработчик дублировался (значение менялось N раз, ререндер шёл N раз).
 * Функция годится ТОЛЬКО для панели настроек: в wire() флаг уже выставлен,
 * и обработчик был бы молча потерян. */
let uiBound = false;
function onFirstBind(node, type, fn) {
  if (uiBound || !node) return;
  node.addEventListener(type, fn);
}

function bindSettings() {
  populateProviderSelect();
  populateOcrSelect();
  bindSel('opt-ocr');
  bindSel('opt-detect');
  bindSel('opt-lang');
  bindSel('opt-trlang');
  bindSel('opt-ai');
  bindInp('opt-key');
  bindInp('opt-aiurl');
  bindInp('opt-zenrelay');
  setupModelUi();
  bindSel('opt-voicebackend');
  bindInp('opt-proxy');
  bindInp('opt-backend-url');
  bindInp('opt-backend-token');
  bindSel('opt-res');
  bindSel('opt-zoom');
  bindSel('opt-caption');
  bindSel('opt-biling');
  bindRange('opt-fps', 'opt-fps-v', (v) => settings.fps = +v, 'fps');
  bindRange('opt-gap', 'opt-gap-v', (v) => settings.gap = +v, (v) => (v / 1000).toFixed(2) + ' c');
  bindRange('opt-mvol', 'opt-mvol-v', (v) => settings.mvol = +v, (v) => v + '%');
  onFirstBind($('opt-music'), 'change', (e) => {
    if (!e.target.files.length) return;
    const f = e.target.files[0];
    setMusic(f);
    toast('Музыка: ' + f.name);
  });
  uiBound = true;
}

function bindSel(id) {
  const elEl = $(id);
  const key = id.replace(/^opt-/, '');
  elEl.value = settings[key] != null ? settings[key] : '';
  onFirstBind(elEl, 'change', () => {
    settings[key] = elEl.value;
    if (key === 'ai') {
      const p = provider(settings.ai);
      if (settings.aimodel && p.models && !p.models.some(m => m.id === settings.aimodel)) {
        settings.aimodel = p.models[0] ? p.models[0].id : 'openai';
      } else if (!settings.aimodel) {
        settings.aimodel = p.models[0] ? p.models[0].id : 'openai';
      }
      populateModelSelect();
    }
    if (key === 'ai' || key === 'ocr') syncProviderUi();
    autoSaveTimer();
  });
}

/* Провайдер в каталоге? */
function defaultModelFor(pid) {
  const p = provider(pid);
  return p.models[0] ? p.models[0].id : '';
}

function populateProviderSelect() {
  const sel = $('opt-ai');
  sel.replaceChildren();
  const entries = Object.entries(PROVIDERS);
  entries.sort((a, b) => {
    const ka = (a[1].curated ? 0 : 1), kb = (b[1].curated ? 0 : 1);
    if (ka !== kb) return ka - kb;
    const fa = (a[1].key === false ? 0 : 1), fb = (b[1].key === false ? 0 : 1);
    if (fa !== fb) return fa - fb;
    return a[1].name.localeCompare(b[1].name, 'ru');
  });
  // custom без моделей в каталоге, но его нельзя выкидывать из селекта:
  // иначе при settings.ai === 'custom' поле молча показывало Pollinations,
  // а в настройках оставался 'custom' — UI врал о выбранном провайдере.
  sel.appendChild(el('option', { value: 'custom' }, ['Свой OpenAI-совместимый · впишите адрес и модель']));
  entries.forEach(([id, p]) => {
    if (id === 'custom') return;
