  if (typeof role.volumeNum === 'number' && isFinite(role.volumeNum)) {
    pct = role.volumeNum;
  } else {
    const m = /^\s*([+-]?\d+(?:\.\d+)?)\s*%\s*$/.exec(String(role.volume || ''));
