};

/* Ссылка на страницу, где взять ключ. Для каталога models.dev — сайт
 * провайдера из его endpoint (реальный домен). */
export function providerKeyUrl(pid) {
  const p = provider(pid);
  if (p.key !== true) return '';
  if (pid in PROVIDER_KEY_URL) return PROVIDER_KEY_URL[pid];
  try {
    return new URL(p.endpoint).origin + '/';
  } catch (e) {
    return '';
  }
}

export function isOrchestrator(pid) {
  return provider(pid).orchestrator === true;
}

export function provider(id) { return PROVIDERS[id] || PROVIDERS.custom; }

export function isFreeModel(pid, mid) {
  const m = (provider(pid).models || []).find((x) => x.id === mid);
  return !!(m && (m.free || m.nokey || provider(pid).key === false));
}

/* Демо-модель «без ключа» у провайдера с ключом (напр. free tier Zen:
 * big-pickle и др.) — ходит через релей, который добавляет identity-заголовки
 * opencode CLI. */
export function modelDemoKeyless(pid, mid) {
  const m = (provider(pid).models || []).find((x) => x.id === mid);
  return !!(m && m.nokey === true);
}

export function providerNeedsKey(pid) { return provider(pid).key === true; }

/* Категория модели: 'free' (без затрат; включает без-ключ) или 'paid'. */
export function modelKind(pid, mid) {
  const p = provider(pid);
  if (p.key === false) return 'free';
  const m = (p.models || []).find((x) => x.id === mid);
  return m && m.free === true ? 'free' : 'paid';
}

/* Метаданные модели для пикера/фильтров. */
const SMART_KEYS = /reason|rational|thinking|thinker|opus|sonnet|pro$|ultra|max$|flash-thinking|r1|r2|qwq|\bo1\b|\bo2\b|\bo3\b|\bo4\b|grok-3|grok-4|deepseek-v4|deepseek-r1|deepseek-chat|glm-5|kimi-k3|qwen3-(235|430|max)|premium|200b|230b|235b|250b|300b|397b|400b|405b|430b|500b|545b|600b|671b|750b|1\.5-trillion|trillion/i;
const DUMB_KEYS = /\bmini\b|\blite\b|\blight\b|\bsmall\b|\btiny\b|\bfast\b|\bflash\b|\bhaiku\b|\binstant\b|\bnano\b|\bmicro\b|\bpico\b|\bsprint\b|\bcheap\b|\bquick\b|\bcompact\b|\bpixel\b|\b0\.\db\b|\b1\.5b\b|\b2b\b|\b3b\b|\b4b\b|\b7b\b|\b8b\b|\b9b\b|\b10b\b|\b12b\b|\b14b\b|\b18b\b|\b24b\b|\b27b\b|\b32b\b|\b33b\b|\b34b\b|\b35b\b|\b40b-a3b\b|\b56b-a3b\b|\b76b-a3b\b|\bgpt-oss-20b\b/i;

/* «Умные или глупые» по объёму/классу: числительные «70B» и выше считаем
 * умными, компактные имена (mini/flash/haiku/nano/…b) — быстрыми/глупыми. */
export function isSmartModel(pid, mid) {
  const p = provider(pid);
  const m = (p.models || []).find((x) => x.id === mid) || {};
  const s = (((m.label || '') + ' ' + mid) || '').toLowerCase();
  const numB = s.match(/(\d+(?:\.\d+)?)\s*b\b/);
  if (numB) return parseFloat(numB[1]) >= 32;
  if (DUMB_KEYS.test(s)) return false;
  if (SMART_KEYS.test(s)) return true;
  return true; // неопределённые каталоговые — считаем умными (оптимизм)
}

/* Метаданные модели для пикера/фильтров. */
export function modelMeta(pid, mid) {
  const p = provider(pid);
  const m = (p.models || []).find((x) => x.id === mid) || {};
  return {
    pid,
    mid,
    label: m.label || mid,
    providerName: (p.name || pid).split(' ·')[0],
    nokey: p.key === false || m.nokey === true,
    free: modelKind(pid, mid) === 'free',
    paid: modelKind(pid, mid) === 'paid',
    vision: p.vision === true,
    curated: p.curated === true,
    requiresKey: p.key === true,
    smart: isSmartModel(pid, mid),
    orchestrator: p.orchestrator === true,
  };
}

/* ================================================================
 * Живая проверка модели («отвечает ли реально»).
 * Статус кэшируется в MODEL_HEALTH на время сессии.
 * ================================================================ */
export const MODEL_HEALTH = new Map(); // `${pid}::${mid}` -> {ok,ms,err,ts}

export async function probeModel(settings, pid, mid) {
  const key = pid + '::' + mid;
  const s = { ...settings, ai: pid, aimodel: mid };
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), 20000);
  const t0 = performance.now();
  try {
    await chat(s, [{ role: 'user', content: 'ping' }], { signal: ctl.signal, minGap: 0 });
    const res = { ok: true, ms: Math.round(performance.now() - t0), err: '', ts: Date.now() };
    MODEL_HEALTH.set(key, res);
    return res;
  } catch (e) {
    const res = { ok: false, ms: Math.round(performance.now() - t0), err: String((e && e.message) || e).slice(0, 140), ts: Date.now() };
    MODEL_HEALTH.set(key, res);
    return res;
  } finally {
    clearTimeout(timer);
  }
}

/* Умеет ли провайдер обрабатывать картинки (vision). */
export function providerHasVision(pid) {
  return provider(pid).vision === true;
}

/* Бесплатные модели Pollinations (tier=anonymous). Динамически обновляется. */
export const FREE_MODELS_FALLBACK = ['openai'];
export let FREE_MODELS = FREE_MODELS_FALLBACK.slice();

/** Подмешать живой список анонимных моделей в каталог провайдера.
 *  Раньше refreshFreeModels() только менял FREE_MODELS, который никто не
 *  читал: кнопка «обновить список» показывала тост, а пикер отдавал тот же
 *  статичный curated-список. Возвращает, сколько моделей добавилось. */
export function mergeFreeModels(pid, list) {
  const p = PROVIDERS[pid];
  if (!p || !Array.isArray(p.models) || !Array.isArray(list)) return 0;
  const have = new Set(p.models.map(m => m.id));
  let added = 0;
  for (const id of list) {
    if (typeof id !== 'string' || !id || have.has(id)) continue;
    have.add(id);
    p.models.push({ id, free: true });
    added++;
  }
  return added;
}

export async function refreshFreeModels() {
  try {
    const r = await fetch(POLLIMAGES + '/models');
    if (!r.ok) throw new Error('pollinations /models ' + r.status);
    const list = await r.json();
    const set = new Set();
    for (const m of Array.isArray(list) ? list : []) {
      if (m && m.tier === 'anonymous' && typeof m.name === 'string' && m.name) {
        set.add(m.name);
        for (const a of m.aliases || []) set.add(a);
      }
    }
    FREE_MODELS = set.size ? [...set] : FREE_MODELS_FALLBACK.slice();
  } catch (e) {
    FREE_MODELS = FREE_MODELS_FALLBACK.slice();
  }
  return FREE_MODELS.slice();
}

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

/* Вытащить валидный JSON из ответа (иногда рядом текст) */
export function parseJsonLoose(s) {
  if (!s) return null;
  s = s.trim();
  try { return JSON.parse(s); } catch (e) { /* дальше ищем блок */ }
  const obj = s.match(/\{[\s\S]*\}/);
  if (obj) { try { return JSON.parse(obj[0]); } catch (e) {} }
  const arr = s.match(/\[[\s\S]*\]/);
  if (arr) { try { return JSON.parse(arr[0]); } catch (e) {} }
  return null;
}

/* Проверка: надо ли подождать из-за лимитов (429).
 * Счётчик ожиданий ведёт каждый вызов, а не этот хелпер. */

/** chat — единая точка вызова для любого провайдера из каталога.
 * settings: {ai:'pollinations'|'openrouter'|'openai'|'anthropic'|'gemini'|..., key, aiurl, aimodel, aiGap}
 * messages: [{role, content}] — content может быть строкой или массивом частей.
 * opts: {json:bool, minGap:ms}
 */
export async function chat(settings, messages, opts = {}) {
  const p = provider(settings.ai);
  const model = settings.aimodel || (p.models[0] ? p.models[0].id : 'openai');
  settings = { ...settings, aimodel: model };
  if (p.gemini) return chatGemini(settings, messages, opts);
  if (p.anthropic) return chatAnthropic(settings, messages, opts);
  let endpoint = settings.ai === 'custom' ? (settings.aiurl || '') : p.endpoint;
  const key = settings.key || '';
  if (modelDemoKeyless(settings.ai, model) && !key) {
    const relay = (settings.zenRelay || '').trim().replace(/\/+$/, '');
    if (!relay) {
      throw new Error(
        `«${model}» — free tier OpenCode Zen без ключа. Браузер не может напрямую ` +
        'отправить identity-заголовки opencode CLI (User-Agent, x-opencode-*), поэтому ' +
        'такие модели работают через мини-релей: команда «node relay/zen-relay.mjs», ' +
        'её URL задайте в настройках («URL Zen-релея»), либо добавьте ключ Zen.'
      );
    }
    endpoint = relay + '/v1/chat/completions';
  }
  if (!endpoint) throw new Error('Свой провайдер: не задан адрес OpenAI-совместимого API');
  return openAICompat({
    name: (p.name || settings.ai).split(' ·')[0],
    endpoint,
    headers: p.headers || {},
    key,
    model,
    messages: messagesWithImages(messages, opts.images),
    json: opts.json,
    gap: opts.minGap ?? settings.aiGap ?? 2500,
    signal: opts.signal,
  });
}

/* Превращает массив dataURL-картинок в OpenAI-совместимые parts */
function messagesWithImages(messages, images) {
  if (!images || !images.length) return messages;
  const img = images[0];
  const body = { type: 'image_url', image_url: { url: img && (img.dataURL || img) } };
  return messages.map(m => {
    if (m.role !== 'user') return m;
    if (typeof m.content === 'string') m.content = [{ type: 'text', text: m.content }];
    if (Array.isArray(m.content)) m.content = [...m.content, body];
    return m;
  });
}

/* Отправка картинки vision-провайдеру поверх текстового контекста */
export async function chatWithImage(settings, messages, imageDataURL) {
  settings = { ...settings, aimodel: settings.aimodel || provider(settings.ai).models[0]?.id || 'openai' };
  const p = provider(settings.ai);
  if (!p.vision) throw new Error('«' + (p.name || settings.ai) + '» не умеет смотреть изображения (выберите vision-провайдер)');
  const text = messages.filter(m => m.role !== 'system').map(m => (m.role === 'user' ? 'Пользователь: ' : 'ИИ: ') + m.content).join('\n');
  if (p.gemini) return chatGeminiVision(settings, imageDataURL, text);
  if (p.anthropic) return chatAnthropicVision(settings, imageDataURL, text);
  return openAICompat({
    name: (p.name || settings.ai).split(' ·')[0],
    endpoint: settings.ai === 'custom' ? (settings.aiurl || '') : p.endpoint,
    headers: p.headers || {},
    key: settings.key || '',
    model: settings.aimodel,
    messages: [{ role: 'user', content: [{ type: 'text', text }, { type: 'image_url', image_url: { url: imageDataURL } }] }],
  });
}

/* Универсальный вызов OpenAI-совместимых API (Pollinations/OpenRouter/OpenAI/
 * Groq/DeepSeek/Mistral/Together/xAI/Perplexity/Cerebras/custom) с ретраями
 * при 429/5xx и парсингом JSON-ответа. */
async function openAICompat({ name, endpoint, headers = {}, key = '', model, messages, json = false, gap = 2500, signal }) {
  const hd = { 'Content-Type': 'application/json', ...(key ? { Authorization: 'Bearer ' + key } : {}), ...headers };
  let attempt = 0, waits = 0;
  let wantJsonMode = json; // не все провайдеры понимают response_format
  while (true) {
    const body = { model, messages, temperature: temperatureFor(model, wantJsonMode) };
    if (body.temperature === undefined) delete body.temperature;
    if (wantJsonMode) body.response_format = { type: 'json_object' };
    try {
      const r = await fetch(endpoint, { method: 'POST', headers: hd, body: JSON.stringify(body), signal });
      if (r.status === 429 && waits < 3) { waits++; await sleep(5000 * waits); continue; }
      if (!r.ok) {
        const t = await r.text().catch(() => '');
        // провайдер не умеет response_format — пробуем без него, это не ошибка запроса
        if (wantJsonMode && r.status === 400 && /response_format|json_object/i.test(t)) {
          wantJsonMode = false; attempt = 0; continue;
        }
        const err = new Error(`${name} ${r.status}: ${t.slice(0, 180)}`);
        err.status = r.status;
        throw err;
      }
      const j = await r.json();
      let out = (j.choices && j.choices[0] && (j.choices[0].message || {}).content) || '';
      if (wantJsonMode) {
        const parsed = parseJsonLoose(typeof out === 'string' ? out : JSON.stringify(out));
        if (parsed) return parsed;
      }
      return out;
    } catch (e) {
      if (e.name === 'AbortError') throw e;
      // 4xx (кроме 429, который обработан выше) — запрос неверный, повтор не поможет
      if (e.status >= 400 && e.status < 500) throw e;
      if (attempt >= 3) throw e;
      await sleep(gap * (attempt + 1));
      attempt++;
    }
  }
}

/* reasoning-модели (o1/o3/o4, gpt-5*, codex) принимают только temperature=1,
 * любое другое значение даёт 400. Для них поле просто не отправляется. */
const REASONING_MODELS = /^(o[1-9]\d*(\.\d+)?(-|$)|gpt-5|codex)/i;

function temperatureFor(model, json) {
  if (json) return 0.1;
  if (REASONING_MODELS.test(String(model || ''))) return undefined;
  return 0.5;
}

export { temperatureFor, REASONING_MODELS };

/* Текст из parts OpenAI-совместимого формата (после подстановки картинок). */
function textOf(content) {
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) {
    return content.map(p => (p && typeof p.text === 'string' ? p.text : (p && p.type === 'image_url' ? '' : ''))).filter(Boolean).join(' ');
  }
  return content == null ? '' : String(content);
}

async function chatGemini(settings, messages, opts = {}) {
  const model = settings.aimodel || 'gemini-2.0-flash';
  const key = settings.key || '';
  if (!key) throw new Error('Gemini: нужен API-ключ');
  const gap = opts.minGap ?? settings.aiGap ?? 2500;
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`;
  // system-роль Gemini не знает: раньше системный промпт уходил как ещё один
  // user-turn, и модель отвечала на него вместо вопроса.
  const sys = messages.filter(m => m.role === 'system').map(m => textOf(m.content)).join('\n\n');
  const parts = messages
    .filter(m => m.role !== 'system')
    .map(m => ({ role: m.role === 'assistant' ? 'model' : 'user', parts: [{ text: textOf(m.content) }] }));
  if (!parts.length) parts.push({ role: 'user', parts: [{ text: 'ping' }] });
  const payload = { contents: parts };
  if (sys.trim()) payload.systemInstruction = { parts: [{ text: sys }] };
  const img = opts.images && opts.images[0];
  if (img && parts.length) {
    const d = img.dataURL || img;
    const inl = d.split(';base64,');
    parts[parts.length - 1].parts.push({ inline_data: { mime_type: inl[0].split(':')[1] || 'image/jpeg', data: inl[1] } });
  }
  let attempt = 0, waits = 0;
  while (true) {
    try {
      const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload), signal: opts.signal });
      if (r.status === 429 && waits < 3) { waits++; await sleep(5000 * waits); continue; }
      if (!r.ok) { const t = await r.text().catch(() => ''); const e = new Error('Gemini ' + r.status + (t ? ': ' + t.slice(0, 150) : '')); e.status = r.status; throw e; }
      const j = await r.json();
      const out = j.candidates?.[0]?.content?.parts?.map(p => p.text).join('') || '';
      if (!out && j.candidates?.[0]?.finishReason && j.candidates[0].finishReason !== 'STOP') {
        const e = new Error('Gemini ' + j.candidates[0].finishReason + (j.promptFeedback?.blockReason ? ' (' + j.promptFeedback.blockReason + ')' : ''));
        e.status = 400; throw e;
      }
      if (opts.json) { const parsed = parseJsonLoose(out); if (parsed) return parsed; }
      return out;
    } catch (e) {
      if (e.name === 'AbortError') throw e;
      if (e.status >= 400 && e.status < 500) throw e;
      if (attempt >= 3) throw e;
      attempt++;
      await sleep(gap * attempt);
    }
  }
}

async function chatAnthropic(settings, messages, opts = {}) {
  const model = settings.aimodel || 'claude-sonnet-4-5';
  const key = settings.key || '';
  if (!key) throw new Error('Anthropic: нужен API-ключ');
  const welcome = provider(settings.ai);
  const endpoint = settings.ai === 'custom' ? (settings.aiurl || '') : welcome.endpoint;
  const sys = messages.filter(m => m.role === 'system').map(m => textOf(m.content)).join('\n\n');
  let bodyMsgs = messages.filter(m => m.role !== 'system').map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: textOf(m.content) }));
  if (!bodyMsgs.length) bodyMsgs = [{ role: 'user', content: 'ping' }];
  const img = opts.images && opts.images[0];
  if (img && bodyMsgs.length) {
    const d = img.dataURL || img;
    const inl = d.split(';base64,');
    const mime = inl[0].split(':')[1] || 'image/jpeg';
    const content = typeof bodyMsgs[bodyMsgs.length - 1].content === 'string'
      ? [{ type: 'text', text: bodyMsgs[bodyMsgs.length - 1].content }]
      : bodyMsgs[bodyMsgs.length - 1].content;
    content.push({ type: 'image', source: { type: 'base64', media_type: mime, data: inl[1] } });
    bodyMsgs[bodyMsgs.length - 1].content = content;
  }
  const body = { model, max_tokens: 4096, messages: bodyMsgs };
  if (sys.trim()) body.system = sys;
  const gap = opts.minGap ?? settings.aiGap ?? 2500;
  let attempt = 0, waits = 0;
  while (true) {
    try {
      const r = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': key, 'anthropic-version': '2023-06-01' },
        body: JSON.stringify(body),
        signal: opts.signal,
      });
      if (r.status === 429 && waits < 3) { waits++; await sleep(5000 * waits); continue; }
      if (!r.ok) { const t = await r.text().catch(() => ''); const e = new Error('Claude ' + r.status + (t ? ': ' + t.slice(0, 150) : '')); e.status = r.status; throw e; }
      const j = await r.json();
      let out = (j.content || []).map(x => x.text).join('') || '';
      if (opts.json) { const parsed = parseJsonLoose(out); if (parsed) return parsed; }
      return out;
    } catch (e) {
      if (e.name === 'AbortError') throw e;
      if (e.status >= 400 && e.status < 500) throw e;
      if (attempt >= 3) throw e;
      attempt++;
      await sleep(gap * attempt);
    }
  }
}

export async function chatGeminiVision(settings, imageDataURL, prompt) {
  const key = settings.key || '';
  if (!key) throw new Error('Gemini: нужен API-ключ (Опции → ИИ-провайдер → ключ)');
  const model = settings.aimodel || 'gemini-2.0-flash';
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`;
  const inline = imageDataURL.split(';base64,');
  const body = { contents: [{ parts: [{ text: prompt }, { inline_data: { mime_type: inline[0].split(':')[1] || 'image/jpeg', data: inline[1] } }] }] };
  const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  if (!r.ok) throw new Error(`Gemini vision ${r.status}`);
  const j = await r.json();
  return j.candidates?.[0]?.content?.parts?.map(p => p.text).join('') || '';
}

/* ================================================================
 * Высокоуровневые помощники
 * ================================================================ */

/* OCR страницы через vision-провайдера (позиции без bbox, поэтому строки
 * раскладываем в «пузыри» по порядку). */
export async function visionExtractLines(settings, dataURL, langName) {
  const prompt =
    `Прочитай весь текст на этом изображении (${langName}). Это страница манги/комикса. ` +
    `Верни строго JSON массив строк в том порядке, в котором их нужно читать. ` +
    `Внутри double quotes. Не добавляй ничего кроме JSON.`;
  let out;
  const p = provider(settings.ai);
  if (p.gemini) {
    out = await chatGeminiVision(settings, dataURL, prompt);
  } else if (p.anthropic) {
    out = await chatAnthropicVision(settings, dataURL, prompt);
  } else {
    const parts = [{ type: 'text', text: prompt }, { type: 'image_url', image_url: { url: dataURL } }];
    out = await openAICompat({
      name: (p.name || 'API').split(' ·')[0],
      endpoint: settings.ai === 'custom' ? (settings.aiurl || '') : p.endpoint,
      headers: p.headers || {},
      key: settings.key || '',
      model: settings.aimodel || 'openai',
      messages: [{ role: 'user', content: parts }],
      gap: settings.aiGap ?? 4000,
    });
  }
  const arr = parseJsonLoose(out);
  if (Array.isArray(arr)) return arr.filter(s => s && String(s).trim());
  return String(out).split('\n').map(s => s.trim()).filter(Boolean);
}

async function chatAnthropicVision(settings, dataURL, prompt) {
  const key = settings.key || '';
  if (!key) throw new Error('Claude: нужен API-ключ');
  const m = dataURL.match(/^data:([^;]+);base64,(.*)$/s);
  const parts = [{ type: 'text', text: prompt }];
  if (m) parts.push({ type: 'image', source: { type: 'base64', media_type: m[1], data: m[2] } });
  else parts.push({ type: 'image', source: { type: 'url', url: dataURL } });
  const p = provider(settings.ai);
  const endpoint = settings.ai === 'custom' ? (settings.aiurl || '') : p.endpoint;
  const r = await fetch(endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-api-key': key, 'anthropic-version': '2023-06-01' },
    body: JSON.stringify({ model: settings.aimodel || 'claude-sonnet-4-5', max_tokens: 4096, messages: [{ role: 'user', content: parts }] }),
  });
  if (!r.ok) throw new Error(`Claude vision ${r.status}`);
  const j = await r.json();
  return (j.content || []).map(x => x.text).join('') || '';
}

/* Раздать роли: вход — реплики [{idx, page, text}]
 *
 * Сценарий режется на пачки: 700-страничная манга целиком в контекст не
 * влезает, и раньше такой запрос просто падал по размеру. Персонажи из всех
 * пачек объединяются, говорящие нормализуются на стороне вызывающего.
 * Возвращает { characters, items, batches, missing } — items с общим idx,
 * сквозным по всему сценарию. */
const ROLE_BATCH = 60;

export async function analyzeRoles(settings, lines, opts = {}) {
  const langName = opts.langName || '';
  const batches = [];
  for (let i = 0; i < lines.length; i += ROLE_BATCH) batches.push(lines.slice(i, i + ROLE_BATCH));

  const characters = [];
  const items = [];
  const seenChar = new Set();
  const missing = [];

  for (let b = 0; b < batches.length; b++) {
    const part = batches[b];
    const base = b * ROLE_BATCH;
    const sys = 'Ты — режиссёр дубляжа манги/комикса. Определи, кто говорит каждую реплику. ' +
      (langName ? `Язык реплик: ${langName}. ` : '') +
      'Правила:\n' +
      '1. В characters перечисли КАЖДОГО говорящего один раз: {"name":"Имя","gender":"male|female|other"}.\n' +
      '2. В lines верни {"idx":<номер из входа>,"character":"имя ровно как в characters"} для КАЖДОЙ реплики.\n' +
      '3. Имя выбирай устойчиво: один и тот же герой на всех страницах должен называться одинаково, ' +
      'сначала по имени, а не по прозвищу.\n' +
      '4. Закадровый текст, внутренний монолог и мысли автора — character: "Нарратор".\n' +
      '5. Если говорящего определить невозможно — character: "?" (не выдумывай имя).\n' +
      '6. Верни строго JSON без пояснений.';
    const payload = part.map((l) => ({ idx: l.idx, page: l.page, text: l.text }));
    const out = await chat(settings, [
      { role: 'system', content: sys },
      { role: 'user', content: 'Реплики (JSON): ' + JSON.stringify(payload) },
    ], { json: true, minGap: 6000 });
    const parsed = parseJsonLoose(typeof out === 'string' ? out : JSON.stringify(out));
    if (!parsed || !Array.isArray(parsed.lines)) {
      missing.push({ from: base, to: base + part.length - 1 });
      continue;
    }
    for (const c of Array.isArray(parsed.characters) ? parsed.characters : []) {
      const name = String((c && c.name) || '').trim();
      const key = name.toLowerCase().replace(/ё/g, 'е');
      if (!name || seenChar.has(key)) continue;
      seenChar.add(key);
      characters.push({ name, gender: (c && c.gender) || 'other' });
    }
    for (const it of parsed.lines) {
      const idx = Number(it && it.idx);
      if (!Number.isInteger(idx) || idx < 0 || idx >= lines.length) continue;
      items.push({ idx, character: String((it && it.character) || '').trim() });
    }
  }

  if (!items.length && !characters.length) return null;
  return { characters, items, batches: batches.length, missing };
}

/* Перевод реплик батчами. Возвращает массив той же длины, что и lines;
 * непереведённые места — null (раньше мусорный idx вида "x" писался в
 * out["x"], а в середине массива оставались дырки без объяснения). */
export async function translateLines(settings, lines, toLang) {
  const out = new Array(lines.length).fill(null);
  const B = 30;
  for (let i = 0; i < lines.length; i += B) {
    const batch = lines.slice(i, i + B).map((l, k) => ({ idx: i + k, text: l.text }));
    const sys = `Ты — профессиональный переводчик манги/комиксов. Переведи реплики на язык: ${toLang}. ` +
      `Сохрани смысл обращений/имён. Верни строго JSON: [{"idx":0,"text":"..."}]`;
    const outText = await chat(settings, [
      { role: 'system', content: sys },
      { role: 'user', content: 'Реплики: ' + JSON.stringify(batch) },
    ], { json: true, minGap: 4000 });
    const parsed = parseJsonLoose(typeof outText === 'string' ? outText : JSON.stringify(outText));
    if (!Array.isArray(parsed)) {
      const raw = typeof outText === 'string' ? outText : JSON.stringify(outText);
      throw new Error('API вернул не JSON-массив: ' + String(raw).slice(0, 120));
    }
    for (const it of parsed) {
      if (!it || typeof it !== 'object') continue;
      const n = Number(it.idx);
      if (!Number.isInteger(n) || n < 0 || n >= lines.length) continue; // мусорный idx
      if (typeof it.text !== 'string' || !it.text.trim()) continue;
      out[n] = it.text;
    }
    await sleep(300);
  }
  return out;
}

/** Сколько реплик реально переведено (для честного отчёта в UI). */
export function countTranslated(out) {
  return (out || []).filter(v => typeof v === 'string' && v.trim()).length;
}

#!/usr/bin/env node
/* Zen-релей для VoiceComic.
 *
 * OpenCode Zen free tier («демо-режим», модели big-pickle, mimo-v2.5-free и
 * др.) пускает запросы БЕЗ ключа только при условии, что они «выглядят» как
 * запросы opencode-CLI: нужны identity-заголовки (User-Agent: opencode/<ver>,
 * x-opencode-session/request/client/project), stream:true, tool_choice:auto и
 * официальный набор builtin-тулов. Браузер не может подменить User-Agent, а у
 * zen нет CORS — поэтому для keyless-моделей из PWA/APK нужен этот релей.
 *
 * Понимает два эндпоинта zen (выбираются автоматически по модели):
 *   - /v1/chat/completions — oa-compat модели (big-pickle, mimo-*, nemotron-*,
 *     ling-*, space-bunny-free, deepseek-v4-flash-free);
 *   - /v1/responses       — Responses-модели (muse-spark-*-contributor-free;
 *     тулы конвертируются в Responses-формат и поднимается max_output_tokens);
 *   - jev-*               — это «система решений» структуры state+questions,
 *     не чат; релей возвращает понятную ошибку.
 * Оба пути сворачиваются в обычный JSON chat.completion, так что клиент
 * (non-stream) ничего не знает про SSE.
 *
 * Запуск:        node relay/zen-relay.mjs [порт]
 *                 (порт по умолчанию 8789; можно ZEN_RELAY_PORT=…)
 * Проверка:      curl -s localhost:8789/healthz
 * Пример:
 *   POST http://localhost:8789/v1/chat/completions
 *   { "model":"big-pickle","messages":[{"role":"user","content":"привет"}] }
 *   — демо-модели без ключа; платные — если прислать Authorization: Bearer <ключ Zen>.
 */

import http from 'node:http';
import crypto from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const PORT = Number(process.argv[2] || process.env.ZEN_RELAY_PORT || 8789);
const ZEN = 'https://opencode.ai/zen/v1';
const OPENCODE_VERSION = '1.18.31';
const TOOLS = JSON.parse(readFileSync(path.join(ROOT, 'builtin_tools.json'), 'utf8'));

const RESPONSES_MODELS = /muse-spark-\S*contributor-free/;
const JEV_MODELS = /^jev-/;

const B62 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
function ocId(prefix) {
  const packed = Date.now() * 0x1000;
  let tail = '';
  for (const b of crypto.randomBytes(14)) tail += B62[b % 62];
  return prefix + packed.toString(16).padStart(12, '0').slice(-12) + tail;
}

const PROBE_MSG = { type: 'user', content: 'ping' };

function cors(res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', '*');
  res.setHeader('Access-Control-Expose-Headers', '*');
}

function sendJson(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(body);
}

async function readBody(req) {
  const chunks = [];
  for await (const c of req) chunks.push(c);
  return Buffer.concat(chunks);
}

function identityHeaders(req) {
  const h = {
    'Content-Type': 'application/json',
    'User-Agent': `opencode/${OPENCODE_VERSION}`,
    'x-opencode-client': 'cli',
    'x-opencode-project': 'global',
    'x-opencode-session': ocId('ses_'),
    'x-opencode-request': ocId('msg_'),
    Accept: 'application/json, text/event-stream',
  };
  if (req.headers.authorization) h.Authorization = req.headers.authorization;
  return h;
}

function mergeTools(clientTools) {
  if (Array.isArray(clientTools) && clientTools.length) return [...clientTools];
  return TOOLS;
}

function responsesTools() {
  return TOOLS.map((t) => ({
    type: 'function',
    name: t.function.name,
    description: t.function.description,
    parameters: t.function.parameters,
  }));
}

export function sseFoldChat(raw) {
  let content = '';
  let finish_reason = 'stop';
  let err = null;
  for (const line of raw.split(/\r?\n/)) {
    const s = line.trim();
    if (!s.startsWith('data:')) continue;
    const payload = s.slice(5).trim();
    if (!payload || payload === '[DONE]') continue;
    try {
      const o = JSON.parse(payload);
      // stream=true у zen всегда присылает сначала error-событие
      if (o.error) { err = o.error; continue; }
      const d = o.choices && o.choices[0];
      if (!d) continue;
      if (d.delta && d.delta.content) content += d.delta.content;
      if (d.finish_reason) finish_reason = d.finish_reason;
      if (d.delta && d.delta.reasoning_content) content += '';
    } catch (_) { /* skip partial */ }
  }
  if (err) return { content, finish_reason: 'error', error: errText(err) };
  if (finish_reason === 'length') {
    return { content, finish_reason, error: 'модель упёрлась в лимит длины ответа (сократите запрос)' };
  }
  if (!content.trim()) {
    return { content, finish_reason, error: 'модель вернула пустой ответ' };
  }
  return { content, finish_reason };
}

function errText(e) {
  if (!e) return 'неизвестная ошибка zen';
  if (typeof e === 'string') return e;
  return e.message || e.code || JSON.stringify(e).slice(0, 200);
}

export function sseFoldResponses(raw) {
  let content = '';
  let status = 'completed';
  let stopped = false;
  let err = null;
  let incomplete = null;
  for (const line of raw.split(/\r?\n/)) {
    const s = line.trim();
    if (!s.startsWith('data:')) continue;
    const payload = s.slice(5).trim();
    if (!payload || payload === '[DONE]') continue;
    try {
      const o = JSON.parse(payload);
      if (o.type === 'response.output_text.delta') content += o.delta || '';
      if (o.type === 'response.completed') { status = (o.response && o.response.status) || 'completed'; stopped = true; }
      if (o.type === 'response.incomplete') { incomplete = o.response && o.response.incomplete_details; stopped = true; }
      if (o.type === 'response.failed' || o.type === 'error') { err = o; status = 'failed'; stopped = true; }
      if (o.type === 'response.error') { err = o; status = 'failed'; stopped = true; }
    } catch (_) { /* skip partial */ }
  }
  if (err) return { content, status, stopped, finish_reason: 'error', error: errText(err.error || err.response || err) };
  if (incomplete) {
    return { content, status, stopped, finish_reason: 'error',
      error: 'модель не закончила ответ: ' + (incomplete.reason || 'incomplete') };
  }
  if (status !== 'completed') {
    return { content, status, stopped, finish_reason: 'error', error: 'статус ответа zen: ' + status };
  }
  if (!content.trim()) {
    return { content, status, stopped, finish_reason: 'error', error: 'модель вернула пустой ответ' };
  }
  return { content, status, stopped, finish_reason: 'stop' };
}

export function completionJson(model, result) {
  return {
    id: 'chatcmpl-relay-' + Date.now(),
    object: 'chat.completion',
    created: Math.floor(Date.now() / 1000),
    model,
    choices: [{
      index: 0,
      message: { role: 'assistant', content: result.content || '' },
      finish_reason: result.finish_reason || 'stop',
    }],
    usage: usageOf(result),
  };
}

/* Считаем по-настоящему. Раньше здесь всегда стояли нули — это фиктивные
 * данные, которые выглядят как настоящая телеметрия. */
function usageOf(result) {
  const u = (result && result.usage) || {};
  const prompt = Number(u.prompt_tokens ?? u.input_tokens ?? 0) || 0;
  const completion = Number(u.completion_tokens ?? u.output_tokens ?? 0) || 0;
  if (prompt || completion) {
    return { prompt_tokens: prompt, completion_tokens: completion, total_tokens: prompt + completion };
  }
  // Токенизатор zen не отдаёт, поэтому считаем хотя бы по символам и
  // честно помечаем оценку, чтобы клиент не принял её за точные числа.
  const text = (result && result.content) || '';
  const chars = text.length;
  return {
    prompt_tokens: 0,
    completion_tokens: chars,
    total_tokens: chars,
    estimated: true,
  };
}

async function handleChat(req, res) {
  let body;
  try {
    body = JSON.parse((await readBody(req)).toString('utf8') || '{}');
  } catch (e) {
    return sendJson(res, 400, { error: { type: 'invalid_request_error', message: 'Bad JSON body' } });
  }

  const model = body.model || '';
  if (typeof model !== 'string' || !model.trim()) {
    return sendJson(res, 400, { error: { type: 'invalid_request_error', message: 'model is required' } });
  }
  if (JEV_MODELS.test(model)) {
    return sendJson(res, 400, {
      error: { type: 'model_not_chat', message: `«${model}» (Jev) — это не чат-модель, а «система решений» (state+questions); в VoiceComic не используется.` },
    });
  }

  const h = identityHeaders(req);
  const isResponses = RESPONSES_MODELS.test(model);

  let out;
  let upstreamUrl;
  if (isResponses) {
    upstreamUrl = ZEN + '/responses';
    out = {
      ...body,
      model,
      stream: true,
      tools: responsesTools(),
      tool_choice: 'auto',
      // без запас по токенам muse-модели возвращают «incomplete»
      max_output_tokens: Math.max(body.max_output_tokens || 800, 800),
      input: Array.isArray(body.messages) && body.messages.length
        ? body.messages.map((m) => ({
            role: m.role || 'user',
            content: [{ type: 'input_text', text: textOf(m.content) }],
          }))
        : [{ role: 'user', content: [{ type: 'input_text', text: 'ping' }] }],
    };
    delete out.messages;
    delete out.max_tokens;
  } else {
    upstreamUrl = ZEN + '/chat/completions';
    out = {
      ...body,
      model,
      stream: true,
      tool_choice: body.tool_choice || 'auto',
      tools: mergeTools(body.tools),
      messages: (body.messages && body.messages.length) ? body.messages : [PROBE_MSG],
    };
    delete out.unused;
  }

  let upstream;
  try {
    upstream = await fetch(upstreamUrl, {
      method: 'POST',
      headers: h,
      body: JSON.stringify(out),
      signal: AbortSignal.timeout(90000),
    });
  } catch (e) {
    return sendJson(res, 502, { error: { type: 'relay_error', message: 'Upstream unreachable: ' + e.message } });
  }

  const raw = await upstream.text();
  if (upstream.status !== 200) {
    const ct = (upstream.headers.get('content-type') || '').toLowerCase();
    let payload = { error: { type: 'upstream_error', message: `Zen HTTP ${upstream.status}` } };
    if (ct.includes('json')) {
      try { payload = JSON.parse(raw); } catch (_) { /* keep default */ }
    }
    return sendJson(res, upstream.status, payload);
  }

  const result = isResponses ? sseFoldResponses(raw) : sseFoldChat(raw);
  // Провал больше не прячется за HTTP 200 с пустым content: клиент получал
  // «пустой ответ» без объяснения и без возможности отличить сбой от молчания.
  if (result.error) {
    return sendJson(res, 502, {
      error: { type: isResponses ? 'upstream_failed' : 'upstream_error', message: result.error },
    });
  }
  return sendJson(res, 200, completionJson(model, result));
}

function textOf(content) {
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) {
    return content.map((p) => (p && p.text != null ? p.text : '')).join('\n');
  }
  return String(content || '');
}

const server = http.createServer(async (req, res) => {
  cors(res);
  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    return res.end();
  }
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/healthz') {
    return sendJson(res, 200, { ok: true, zen: ZEN, version: OPENCODE_VERSION, tools: TOOLS.length });
  }
  if (req.method === 'POST' && url.pathname === '/v1/chat/completions') {
    return handleChat(req, res);
  }
  return sendJson(res, 404, { error: { type: 'not_found', message: url.pathname } });
});

server.listen(PORT, () => {
  console.log('zen-relay on :' + PORT + ' → ' + ZEN);
  console.log('демо-модели без ключа:');
  console.log('  chat: big-pickle, mimo-v2.5-free, mimo-v2.6-flash-free, nemotron-3-ultra-free,');
  console.log('        nemotron-3.5-lightning-free, ling-3.0-flash-fin-free, space-bunny-free, deepseek-v4-flash-free');
  console.log('  responses: muse-spark-1.3-contributor-free, muse-spark-1.2-contributor-free');
  console.log('  jev-* — decision-модель, не чат (не поддерживается)');
});

