          sr = MP3_SR_V1[srI];
        } else if (ver === 2) {
          br = MP3_BR_V2[brI];
          sr = MP3_SR_V2s[srI];
        } else { // ver === 0 (V2.5)
          br = MP3_BR_V2[brI];
          sr = MP3_SR_V25[srI];
        }
        const len = Math.floor((ver === 3 ? 144 : 72) * br * 1000 / sr) + pad;
        if (br && sr && len > 0 && i + len <= n) {
          out.push(bytes.subarray(i, i + len));
