      ctx.drawImage(img, 0, 0, cw, ch);
      const sx = cw / (page.w || cw), sy = ch / (page.h || ch);
      (page.bubbles || []).forEach((b, i) => {
        const role = roleById(b.roleId);
        ctx.strokeStyle = role ? role.color : '#ffb454';
        ctx.lineWidth = 2;
