      p.bubblesHaveBoxes = res.boxes !== false;
      setProgress((i + 1) / targets.length, `стр. ${i + 1}: ${res.bubbles.length} реплик`);
    } catch (e) {
      console.error(e);
      toast('OCR: ' + e.message, 'err');
    }
  }
  $('imp-progress').classList.add('hidden');
